INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:analyze','analyze','v','تحلیل کردن','to examine in detail','If so, a doctor could learn about a person’s behavior by analyzing these bumps.','[["If so, a doctor could learn about a person’s behavior by analyzing these bumps.","اگر چنین بود، پزشک می‌توانست با تحلیل این برآمدگی‌ها دربارهٔ رفتار یک شخص چیزهایی بیاموزد."],["Scientists analyzed the data.","دانشمندان داده‌ها را تجزیه و تحلیل کردند."],["Scientists analyzed the water samples.","دانشمندان نمونه‌های آب را تجزیه و تحلیل کردند."]]','ir0',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:average','average','adj','میانگین، معمولی','typical or usual','He created a complex map of an average human head.','[["He created a complex map of an average human head.","او نقشه‌ای پیچیده از یک سر انسانِ متوسط ساخت."],["The average temperature in July is 30 degrees.","میانگین دما در ماه جولای 30 درجه است."],["The average age of the students is twenty.","میانگین سنی دانش آموزان بیست سال است."]]','ir0',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:behavior','behavior','n','رفتار','the way someone acts','Throughout history, human behavior seemed impossible to understand.','[["Throughout history, human behavior seemed impossible to understand.","در طول تاریخ، درک رفتار انسان ناممکن به نظر می‌رسید."],["His behavior in class has improved.","رفتار او در کلاس بهتر شده است."],["The teacher was pleased with the students'' behavior.","معلم از رفتار دانش آموزان راضی بود."]]','ir0',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:complex','complex','adj','پیچیده','/ˈkɑːmpleks/ · complicated','In the early 19th century, a German doctor thought he could answer these complex questions.','[["In the early 19th century, a German doctor thought he could answer these complex questions.","در اوایل قرن نوزدهم، یک پزشک آلمانی فکر کرد که می‌تواند به این پرسش‌های پیچیده پاسخ دهد."],["Photosynthesis is a highly complex process.","فتوسنتز یک فرآیند بسیار پیچیده است."]]','ir0',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:create','create','v','ایجاد کردن، خلق کردن، ساختن','/kriˈeɪt/ · make, produce','Gall wondered if the functions of the brain created bumps on a person’s skull (the skull is the bone around a person’s head).','[["Gall wondered if the functions of the brain created bumps on a person’s skull (the skull is the bone around a person’s head).","گال از خود پرسید که آیا عملکردهای مغز روی جمجمهٔ انسان برآمدگی ایجاد می‌کنند (جمجمه استخوانی است که دور سر انسان را گرفته است)."],["He believes the universe was created by a big explosion.","او معتقد است که جهان بر اثر یک انفجار بزرگ ایجاد شده است."]]','ir0',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:function','function','n','کارکرد، عملکرد؛ مراسم','/ˈfʌŋkʃən/ · purpose, event','He thought it was possible to understand human behavior if we understood how the brain functioned.','[["He thought it was possible to understand human behavior if we understood how the brain functioned.","او فکر می‌کرد اگر بفهمیم مغز چگونه کار می‌کند، درک رفتار انسان ممکن است."],["The church fulfils a valuable social function.","کلیسا یک کارکرد اجتماعی ارزشمند را انجام می‌دهد."],["The function of the heart is to pump blood.","وظیفه قلب پمپاژ خون است."]]','ir0',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:link','link','n','پیوند، ارتباط','/lɪŋk/ · a connection, relation','He believed that each area of the brain was linked to a certain behavior, such as bravery.','[["He believed that each area of the brain was linked to a certain behavior, such as bravery.","او باور داشت که هر ناحیهٔ مغز به رفتار خاصی، مانند شجاعت، مربوط است."],["He retained strong links with the media.","او ارتباط قوی با رسانه‌ها داشت."]]','ir0',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:locate','locate','v','پیدا کردن (مکان)؛ قرار دادن','/ləʊˈkeɪt/ · to find the exact position of; to put in a place','He could analyze the location and size of the bumps on the skull.','[["He could analyze the location and size of the bumps on the skull.","او می‌توانست محل و اندازهٔ برآمدگی‌های روی جمجمه را تحلیل کند."]]','ir0',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
