INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:wonder','wonder','v','تعجب کردن، از خود پرسیدن؛ شگفتی','/ˈwʌndə(r)/ · to think about something with curiosity; amazement','Teachers wondered why some students were good at math but other students were not.','[["Teachers wondered why some students were good at math but other students were not.","معلمان از خود می‌پرسیدند چرا برخی دانش‌آموزان در ریاضی خوب بودند ولی برخی دیگر نه."]]','ir0',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:accurate','accurate','adj','دقیق، درست','/ˈækjərət/ · exact; correct','This method of showing time was useful, but not very accurate.','[["This method of showing time was useful, but not very accurate.","این روش نشان دادن زمان مفید بود، اما چندان دقیق نبود."],["The film is not historically accurate.","فیلم از نظر تاریخی دقیق نیست."],["The report gives an accurate picture.","گزارش تصویری دقیق ارائه می‌دهد."]]','ir0',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
