INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:confuse','confuse','v','گیج کردن؛ اشتباه گرفتن','/kənˈfjuːz/ · to make someone unable to understand clearly','Also, people were confused to see the time on sundials vary with the seasons.','[["Also, people were confused to see the time on sundials vary with the seasons.","همچنین مردم از اینکه می‌دیدند زمانِ ساعت‌های آفتابی با فصل‌ها تغییر می‌کند گیج می‌شدند."]]','ir0',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:develop','develop','v','توسعه دادن، رشد کردن','to grow or make more advanced','About 4,000 years ago, ancient Egyptians developed a 12-hour time system.','[["About 4,000 years ago, ancient Egyptians developed a 12-hour time system.","حدود ۴۰۰۰ سال پیش، مصریان باستان یک نظام زمانی ۱۲ ساعته پدید آوردند."],["The company is developing a new app.","این شرکت در حال توسعه یک برنامه جدید است."],["Children develop very quickly in their first years.","بچه‌ها در سال‌های اول خیلی سریع رشد می‌کنند."]]','ir0',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:difference','difference','n','تفاوت، فرق','/ˈdɪfrəns/ · the way in which things are not the same','The difference was that sand shifted from the top bowl into the bottom bowl.','[["The difference was that sand shifted from the top bowl into the bottom bowl.","تفاوت در این بود که شن از کاسهٔ بالایی به کاسهٔ پایینی جابه‌جا می‌شد."]]','ir0',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:feature','feature','n','ویژگی، خصوصیت','/ˈfiːtʃər/ · characteristic','About 1,000 years ago, an Arab engineer added mechanical features to water clocks.','[["About 1,000 years ago, an Arab engineer added mechanical features to water clocks.","حدود ۱۰۰۰ سال پیش، یک مهندس عرب ویژگی‌های مکانیکی به ساعت‌های آبی افزود."],["Air bags are a standard feature in most new cars.","کیسه هوا یک ویژگی استاندارد در اکثر خودروهای جدید است."],["The app has many useful features.","این برنامه دارای بسیاری از ویژگی‌های مفید است."]]','ir0',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
