INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:environment','environment','n','محیط، محیط زیست','/ɪnˈvaɪrənmənt/ · surroundings; the natural world','Bacteria—tiny living things—exist everywhere in the environment.','[["Bacteria—tiny living things—exist everywhere in the environment.","باکتری‌ها — موجودات زندهٔ ریز — همه جای محیط وجود دارند."],["We''re trying to create a better business environment.","ما در تلاش هستیم تا فضای کسب و کار بهتری ایجاد کنیم."],["We must protect the environment.","ما باید از محیط زیست محافظت کنیم."]]','ir0',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
