INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:harm','harm','n','آسیب، ضرر؛ آسیب رساندن','/hɑːm/ · damage or injury; to hurt or damage','Scientists know that bacteria can harm and can help humans.','[["Scientists know that bacteria can harm and can help humans.","دانشمندان می‌دانند که باکتری‌ها هم می‌توانند به انسان آسیب بزنند و هم کمک کنند."]]','ir0',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:infect','infect','v','آلوده کردن، مبتلا کردن','/ɪnˈfekt/ · to give a disease to a person, animal or plant','If a person drinks the dirty water, the bacteria will infect his digestive system.','[["If a person drinks the dirty water, the bacteria will infect his digestive system.","اگر کسی آب آلوده بنوشد، باکتری‌ها دستگاه گوارش او را آلوده می‌کنند."]]','ir0',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:prevent','prevent','v','جلوگیری کردن','to stop something from happening','However, there are ways to prevent getting sick.','[["However, there are ways to prevent getting sick.","با این حال، راه‌هایی برای پیشگیری از بیمار شدن وجود دارد."],["Washing hands prevents disease.","شستن دست‌ها از بیماری جلوگیری می‌کند."],["Washing your hands can prevent illness.","شستن دست‌ها می‌تواند از بیماری جلوگیری کند."]]','ir0',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:proceed','proceed','v','ادامه دادن، پیش رفتن','/prəˈsiːd/ · continue to do sth','As he proceeded to watch, the things moved.','[["As he proceeded to watch, the things moved.","همان‌طور که به تماشا ادامه داد، آن چیزها حرکت کردند."],["Work is proceeding according to plan.","کار طبق برنامه پیش می‌رود."]]','ir0',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:react','react','v','واکنش نشان دادن','/riˈækt/ · to behave in a particular way as a response','For instance, he found that one reaction of carbolic acid (a strong chemical) was to destroy bacteria on laboratory equipment.','[["For instance, he found that one reaction of carbolic acid (a strong chemical) was to destroy bacteria on laboratory equipment.","برای نمونه، او دریافت که یکی از واکنش‌های اسید کربولیک (یک مادهٔ شیمیایی قوی) از بین بردن باکتری‌ها روی تجهیزات آزمایشگاه بود."]]','ir0',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:transfer','transfer','v','منتقل کردن، انتقال دادن','/trænsˈfɜːr/ · move','Some diseases easily transfer from one person to another.','[["Some diseases easily transfer from one person to another.","برخی بیماری‌ها به‌آسانی از فردی به فرد دیگر منتقل می‌شوند."],["I''d like to transfer $500 to my checking account.","من می‌خواهم 500 دلار به حساب جاری خود منتقل کنم."]]','ir0',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:assist','assist','v','کمک کردن، یاری رساندن','/əˈsɪst/ · to help someone do something','The government would assist 300 to 500 million people to move from farms to cities by 2020.','[["The government would assist 300 to 500 million people to move from farms to cities by 2020.","دولت تا سال ۲۰۲۰ به ۳۰۰ تا ۵۰۰ میلیون نفر کمک می‌کرد تا از مزرعه‌ها به شهرها کوچ کنند."]]','ir0',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:assume','assume','v','فرض کردن، پنداشتن','/əˈsuːm/ · presume','Each boy assumed he would be a farmer when he grew up.','[["Each boy assumed he would be a farmer when he grew up.","هر پسری فرض می‌کرد که وقتی بزرگ شود کشاورز خواهد شد."],["I think we can safely assume that he is out of town.","فکر می‌کنم با خیال راحت می‌توانیم فرض کنیم که او خارج از شهر است."],["I assume you have heard the news.","فکر می‌کنم شما این خبر را شنیده اید."]]','ir0',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:community','community','n','جامعه، اجتماع','/kəˈmjuːnəti/ · society','And each girl assumed she would become the wife of a farmer in the community.','[["And each girl assumed she would become the wife of a farmer in the community.","و هر دختری فرض می‌کرد که همسر یک کشاورز در همان جامعه خواهد شد."],["The festival was a great way for the local community to get together.","این جشنواره راهی عالی برای اجتماع محلی بود."],["The community built a new park.","جامعه یک پارک جدید ساخت."]]','ir0',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:consequence','consequence','n','پیامد، نتیجه','/ˈkɑːnsɪkwens/ · result','As a consequence, the traditional way of life in China is changing.','[["As a consequence, the traditional way of life in China is changing.","در نتیجه، شیوهٔ سنتی زندگی در چین در حال تغییر است."],["What were the economic consequences of the war?","پیامدهای اقتصادی جنگ چه بود؟"],["Every decision has consequences.","هر تصمیمی عواقبی دارد."]]','ir0',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:define','define','v','تعریف کردن، مشخص کردن','/dɪˈfaɪn/ · describe','When the boys and girls grew up and got married, their lives were clearly defined.','[["When the boys and girls grew up and got married, their lives were clearly defined.","وقتی پسران و دختران بزرگ می‌شدند و ازدواج می‌کردند، زندگی‌شان به‌روشنی مشخص بود."],["There are many definitions of the word ''feminism''.","تعاریف زیادی از کلمه \"فمینیسم\" وجود دارد."],["How do you define success?","موفقیت را چگونه تعریف می‌کنید؟"]]','ir0',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:factor','factor','n','عامل','/ˈfæktər/ · one of several things that influence sth','In the last 50 years, several factors have caused young adults to leave the farms.','[["In the last 50 years, several factors have caused young adults to leave the farms.","در ۵۰ سال گذشته، چند عامل باعث شده‌اند جوانان مزرعه‌ها را ترک کنند."],["Obesity is a major risk factor for heart disease.","چاقی یک عامل خطر اصلی برای بیماری قلبی است."],["Diet is a key factor in health.","رژیم غذایی یک عامل کلیدی در سلامتی است."]]','ir0',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:physical','physical','adj','جسمی، بدنی؛ فیزیکی','/ˈfɪzɪkəl/ · related to someone''s body · ≠ mental','City jobs seemed physically easier than farming.','[["City jobs seemed physically easier than farming.","کارهای شهری از نظر جسمی آسان‌تر از کشاورزی به نظر می‌رسید."],["She was in constant physical pain.","او مدام درد جسمی داشت."]]','ir0',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:seek','seek','v','جستجو کردن، به دنبال چیزی بودن','/siːk/ · search, try to get (past: sought /sɔːt/)','They are seeking jobs in a city.','[["They are seeking jobs in a city.","آن‌ها در شهر به دنبال کار هستند."],["During the war, she sought asylum in Spain.","در طول جنگ، او از اسپانیا درخواست پناهندگی کرد."]]','ir0',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:sufficient','sufficient','adj','کافی','/səˈfɪʃənt/ · enough · ≠ insufficient','Farming did not provide sufficient money to buy computers or cell phones.','[["Farming did not provide sufficient money to buy computers or cell phones.","کشاورزی پول کافی برای خرید رایانه یا تلفن همراه فراهم نمی‌کرد."],["He had an income which was sufficient for his needs.","درآمدی داشت که برای نیازهایش کافی بود."],["We have sufficient food for a week.","برای یک هفته غذای کافی داریم."]]','ir0',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:tradition','tradition','n','سنت، رسم','/trəˈdɪʃn/ · a belief or custom passed down over time','Farming was the traditional way of life for Chinese people.','[["Farming was the traditional way of life for Chinese people.","کشاورزی شیوهٔ سنتی زندگی مردم چین بود."]]','ir0',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:area','area','n','منطقه، ناحیه؛ حوزه','/ˈeriə/ · region, zone','The Burj Khalifa is one of many skyscrapers constructed in different areas of the world recently.','[["The Burj Khalifa is one of many skyscrapers constructed in different areas of the world recently.","برج خلیفه یکی از آسمان‌خراش‌های بسیاری است که اخیراً در نقاط مختلف جهان ساخته شده‌اند."],["Crime rates are much higher in urban areas.","نرخ جرم و جنایت در مناطق شهری بسیار بالاتر است."]]','ir0',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:construct','construct','v','ساختن، بنا کردن','/kənˈstrʌkt/ · build','The Burj Khalifa is one of many skyscrapers constructed in different areas of the world recently.','[["The Burj Khalifa is one of many skyscrapers constructed in different areas of the world recently.","برج خلیفه یکی از آسمان‌خراش‌های بسیاری است که اخیراً در نقاط مختلف جهان ساخته شده‌اند."],["The hotel is currently under construction.","این هتل در حال حاضر در حال ساخت است."],["The bridge was constructed in 1890.","این پل در سال 1890 ساخته شد."]]','ir0',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:design','design','v','طراحی کردن','/dɪˈzaɪn/ · plan','These structures used a new construction design.','[["These structures used a new construction design.","این سازه‌ها از طرح ساخت جدیدی استفاده کردند."],["She designed a new logo for the company.","او لوگوی جدیدی برای این شرکت طراحی کرد."]]','ir0',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
