INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:major','major','adj','اصلی، مهم، عمده','/ˈmeɪdʒər/ · main, important','Two major inventions in the 19th century made the construction of taller buildings possible.','[["Two major inventions in the 19th century made the construction of taller buildings possible.","دو اختراع مهم در قرن نوزدهم ساخت ساختمان‌های بلندتر را ممکن کرد."],["The use of drugs is a major problem.","استفاده از مواد مخدر یک مشکل اساسی است."]]','ir0',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
