INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:structure','structure','n','ساختار، ساختمان','/ˈstrʌktʃər/ · n., v. · building or form','About 2,800 years ago, the tallest structure in the world was the Great Pyramid of Giza in ancient Egypt.','[["About 2,800 years ago, the tallest structure in the world was the Great Pyramid of Giza in ancient Egypt.","حدود ۲۸۰۰ سال پیش، بلندترین سازهٔ جهان هرم بزرگ جیزه در مصر باستان بود."],["the structure of an atom","ساختار یک اتم"],["The structure of DNA is a double helix.","ساختار DNA یک مارپیچ دوگانه است."]]','ir0',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
