INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:available','available','adj','در دسترس، موجود','/əˈveɪləbəl/ · accessible','The diet of early humans depended on what foods were available to them.','[["The diet of early humans depended on what foods were available to them.","رژیم غذایی انسان‌های نخستین به غذاهایی بستگی داشت که در دسترسشان بود."],["Tickets are available from the box office.","بلیط از گیشه موجود است."],["Is this room available tonight?","آیا این اتاق امشب موجود است؟"]]','ir0',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:culture','culture','n','فرهنگ','customs and beliefs of a group','Every culture in the world has its own style of cooking and eating.','[["Every culture in the world has its own style of cooking and eating.","هر فرهنگی در جهان سبک خاص خود را در آشپزی و غذا خوردن دارد."],["Food is an important part of culture.","غذا بخش مهمی از فرهنگ است."],["Food is an important part of every culture.","غذا بخش مهمی از هر فرهنگی است."]]','ir0',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
