INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:ensure','ensure','v','اطمینان حاصل کردن، تضمین کردن','/ɪnˈʃʊər/ · make sure','The animals and crops ensured that the farmers would have a supply of food available to eat.','[["The animals and crops ensured that the farmers would have a supply of food available to eat.","دام‌ها و محصولات کشاورزی تضمین می‌کردند که کشاورزان ذخیره‌ای از غذا برای خوردن داشته باشند."],["The book ensured his success.","کتاب موفقیت او را تضمین کرد."],["Please ensure that all windows are closed.","لطفا مطمئن شوید که همه پنجره‌ها بسته هستند."]]','ir0',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:preserve','preserve','v','حفظ کردن، نگهداری کردن','to keep something in its original state or protect it from harm','They have preserved this eating technique and still use chopsticks today.','[["They have preserved this eating technique and still use chopsticks today.","آن‌ها این شیوهٔ غذا خوردن را حفظ کرده‌اند و هنوز هم از چوب غذاخوری استفاده می‌کنند."],["The ancient city has been well preserved.","شهر باستانی به خوبی حفظ شده است."],["Salt was used to preserve meat.","از نمک برای نگهداری گوشت استفاده می‌شد."]]','ir0',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:rely','rely','v','تکیه کردن','to depend on','People in other cultures rely on pieces of flat bread to pick up food.','[["People in other cultures rely on pieces of flat bread to pick up food.","مردم در فرهنگ‌های دیگر برای برداشتن غذا به تکه‌های نان مسطح متکی‌اند."],["You can rely on me.","میتونی به من تکیه کنی"],["Many farmers rely on rain for their crops.","بسیاری از کشاورزان برای محصولات خود به باران متکی هستند."]]','ir0',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:significant','significant','adj','قابل توجه، مهم','/sɪɡˈnɪfɪkənt/ · important, major','Potatoes, for example, became a significant part of the Irish diet.','[["Potatoes, for example, became a significant part of the Irish diet.","برای مثال، سیب‌زمینی بخش مهمی از رژیم غذایی ایرلندی‌ها شد."],["a significant increase in sales","افزایش قابل توجهی در فروش"],["There was a significant drop in crime.","کاهش قابل توجهی در جرم و جنایت وجود داشت."]]','ir0',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
