INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:display','display','v','نمایش دادن','/dɪˈspleɪ/ · exhibit, show','People enjoy visiting museums to see displays of wonderful paintings and sculptures.','[["People enjoy visiting museums to see displays of wonderful paintings and sculptures.","مردم از بازدید موزه‌ها برای دیدن نقاشی‌ها و مجسمه‌های شگفت‌انگیز لذت می‌برند."],["Family photographs were displayed on the wall.","عکس‌های خانوادگی روی دیوار نصب شده بود."]]','ir0',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:evidence','evidence','n','شواهد، مدرک','/ˈevɪdəns/ · proof, document','They check the museum for evidence, such as fingerprints or a camera photograph.','[["They check the museum for evidence, such as fingerprints or a camera photograph.","آن‌ها موزه را برای یافتن شواهدی مانند اثر انگشت یا عکس دوربین بررسی می‌کنند."],["Evidence shows that global warming is definitely occurring.","شواهد نشان می‌دهد که گرم شدن کره زمین قطعا در حال وقوع است."],["There is no evidence of life on Mars.","هیچ مدرکی از حیات در مریخ وجود ندارد."]]','ir0',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:initial','initial','adj','اولیه، آغازین','/ɪˈnɪʃəl/ · first, primary','Stealing a painting or small object may be easy initially.','[["Stealing a painting or small object may be easy initially.","دزدیدن یک نقاشی یا شیء کوچک ممکن است در ابتدا آسان باشد."],["What was his initial reaction?","واکنش اولیه او چه بود؟"]]','ir0',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:issue','issue','n','موضوع، مسئله؛ صادر کردن','/ˈɪʃuː/ · n., v. · an important topic','If a theft is committed, the museum issues a report to local police.','[["If a theft is committed, the museum issues a report to local police.","اگر سرقتی رخ دهد، موزه گزارشی به پلیس محلی می‌دهد."],["Water purity is a public health issue.","خلوص آب یک مسئله بهداشت عمومی است."],["Climate change is a global issue.","تغییر اقلیم یک مسئله جهانی است."]]','ir0',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:remove','remove','v','برداشتن، حذف کردن','/rɪˈmuːv/ · omit, cut out','They use an alarm system that rings if someone removes a painting.','[["They use an alarm system that rings if someone removes a painting.","آن‌ها از یک سیستم هشدار استفاده می‌کنند که اگر کسی نقاشی‌ای را بردارد به صدا درمی‌آید."],["Remove the old wallpaper and fill any holes in the walls.","کاغذ دیواری قدیمی را بردارید و هر سوراخی را در دیوارها پر کنید."]]','ir0',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:secure','secure','adj','امن، مطمئن؛ به دست آوردن، تأمین کردن','/sɪˈkjʊə(r)/ · safe; to get or achieve something','They use security guards and cameras to watch museum visitors.','[["They use security guards and cameras to watch museum visitors.","آن‌ها از نگهبانان امنیتی و دوربین برای زیر نظر گرفتن بازدیدکنندگان موزه استفاده می‌کنند."]]','ir0',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:steal','steal','v','دزدیدن','/stiːl/ · to take something that belongs to someone else','This means the thief is stealing a piece of our history and culture.','[["This means the thief is stealing a piece of our history and culture.","این یعنی دزد تکه‌ای از تاریخ و فرهنگ ما را می‌دزدد."]]','ir0',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:absorb','absorb','v','جذب کردن','to take in a liquid or gas','The roots of the plants grow in the water mixture and absorb the nutrients.','[["The roots of the plants grow in the water mixture and absorb the nutrients.","ریشه‌های گیاهان در مخلوط آب رشد می‌کنند و مواد مغذی را جذب می‌کنند."],["Plants absorb carbon dioxide.","گیاهان دی اکسید کربن را جذب می‌کنند."],["Plants absorb carbon dioxide from the air.","گیاهان دی اکسید کربن را از هوا جذب می‌کنند."]]','ir0',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:achieve','achieve','v','دست یافتن، به دست آوردن','/əˈtʃiːv/ · get, attain','When the carrots achieve the right size, they will be removed, packaged, transported, and sold.','[["When the carrots achieve the right size, they will be removed, packaged, transported, and sold.","وقتی هویج‌ها به اندازهٔ مناسب برسند، برداشت، بسته‌بندی، حمل و فروخته می‌شوند."],["They achieved high scores on their math tests.","آنها در آزمون‌های ریاضی خود نمرات بالایی کسب کردند."],["She achieved her goal of running a marathon.","او به هدف خود یعنی دوی ماراتن رسید."]]','ir0',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:benefit','benefit','n','سود، مزیت، فایده','/ˈbenəfɪt/ · advantage','If plants cannot grow straight up, they receive less benefit from the sunlight.','[["If plants cannot grow straight up, they receive less benefit from the sunlight.","اگر گیاهان نتوانند صاف به بالا رشد کنند، از نور خورشید بهرهٔ کمتری می‌برند."],["the benefits of a university education","مزایای تحصیل دانشگاهی"],["Exercise has many benefits.","ورزش فواید زیادی دارد."]]','ir0',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:maintain','maintain','v','حفظ کردن، نگه داشتن','to keep in good condition','The soil surrounding the plant roots helps the plants maintain a vertical growth pattern.','[["The soil surrounding the plant roots helps the plants maintain a vertical growth pattern.","خاکِ اطراف ریشه‌ها به گیاهان کمک می‌کند الگوی رشد عمودی خود را حفظ کنند."],["It is hard to maintain an old house.","نگهداری از یک خانه قدیمی سخت است."],["It''s important to maintain a healthy weight.","حفظ وزن سالم بسیار مهم است."]]','ir0',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:principle','principle','n','اصل، قاعده','/ˈprɪnsəpəl/ · rule','The principles of hydroponics are simple, and very little special knowledge or equipment is needed to achieve success.','[["The principles of hydroponics are simple, and very little special knowledge or equipment is needed to achieve success.","اصول هیدروپونیک ساده است و برای رسیدن به موفقیت به دانش یا تجهیزات ویژهٔ چندانی نیاز نیست."],["the basic principles of business management","اصول اساسی مدیریت کسب و کار"],["The machine works on a simple principle.","دستگاه بر اساس یک اصل ساده کار می‌کند."]]','ir0',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:regulation','regulation','n','مقررات، قانون','/ˌreɡjəˈleɪʃən/ · rule','An automatic timer regulates the watering schedule.','[["An automatic timer regulates the watering schedule.","یک زمان‌سنج خودکار برنامهٔ آبیاری را تنظیم می‌کند."],["Smoke detectors must be installed to comply with fire regulations.","دتکتورهای دود باید مطابق با مقررات آتش نشانی نصب شوند."]]','ir0',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:require','require','v','نیاز داشتن، لازم داشتن','/rɪˈkwaɪər/ · need','The water is mixed with nutrients—vitamins and minerals— that plants require in order to grow.','[["The water is mixed with nutrients—vitamins and minerals— that plants require in order to grow.","آب با مواد مغذی — ویتامین‌ها و مواد معدنی — که گیاهان برای رشد به آن‌ها نیاز دارند مخلوط می‌شود."],["Most houseplants require regular watering.","اکثر گیاهان آپارتمانی نیاز به آبیاری منظم دارند."],["The job requires good English.","این شغل به زبان انگلیسی خوب نیاز دارد."]]','ir0',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:strategy','strategy','n','راهبرد، استراتژی','/ˈstrætɪdʒi/ · skilful planning','Hydroponics is one strategy to help provide food to the billions of people on our planet.','[["Hydroponics is one strategy to help provide food to the billions of people on our planet.","هیدروپونیک یکی از راهبردها برای کمک به تأمین غذای میلیاردها انسانِ روی سیارهٔ ما است."],["He was a genius when it came to military strategy.","او در مورد استراتژی نظامی نابغه بود."]]','ir0',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:theory','theory','n','نظریه، تئوری','/ˈθɪəri/ · hypothesis','The theory of hydroponics is not new.','[["The theory of hydroponics is not new.","نظریهٔ هیدروپونیک تازه نیست."],["Darwin''s theory of evolution","نظریه تکامل داروین"],["Darwin developed the theory of evolution.","داروین نظریه تکامل را توسعه داد."]]','ir0',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:transport','transport','v','حمل کردن، جابه‌جا کردن','/ˈtrænspɔːrt/ · carry, transfer','In contrast, a commercial farm might use a hydroponic system to grow thousands of tomatoes and carrots that will eventually be transported to nearby markets and sold.','[["In contrast, a commercial farm might use a hydroponic system to grow thousands of tomatoes and carrots that will eventually be transported to nearby markets and sold.","در مقابل، یک مزرعهٔ تجاری ممکن است از سیستم هیدروپونیک برای پرورش هزاران گوجه‌فرنگی و هویج استفاده کند که سرانجام به بازارهای نزدیک حمل و فروخته می‌شوند."],["The company will arrange transport from the airport.","این شرکت حمل و نقل از فرودگاه را ترتیب خواهد داد."],["Public transport should be free.","حمل و نقل عمومی باید رایگان باشد"]]','ir0',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:affect','affect','v','تأثیر گذاشتن بر','/əˈfekt/ · influence','The powers of nature have always affected human life.','[["The powers of nature have always affected human life.","نیروهای طبیعت همیشه بر زندگی انسان اثر گذاشته‌اند."],["the areas affected by the hurricane","مناطق تحت تاثیر طوفان"],["Lack of sleep can affect your mood.","کمبود خواب می‌تواند بر خلق و خوی شما تأثیر بگذارد."]]','ir0',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:approach','approach','v','نزدیک شدن؛ رویکرد، روش','/əˈproʊtʃ/ · v., n. · move nearer; method','Likewise, a wave might approach land, where it washed away houses and drowned people.','[["Likewise, a wave might approach land, where it washed away houses and drowned people.","به همین ترتیب، ممکن بود موجی به خشکی نزدیک شود و خانه‌ها را با خود ببرد و مردم را غرق کند."],["He approached the issue from a historical perspective.","او از منظر تاریخی به موضوع پرداخت."],["We need a new approach to the problem.","ما به یک رویکرد جدید برای مشکل نیاز داریم."]]','ir0',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:concept','concept','n','مفهوم، انگاره','/ˈkɒnsept/ · idea','The concept of climate change worries humans.','[["The concept of climate change worries humans.","مفهوم تغییرات اقلیمی انسان‌ها را نگران می‌کند."],["She is familiar with basic concepts of psychology.","او با مفاهیم اولیه روانشناسی آشناست."],["The concept of time is difficult to explain.","توضیح مفهوم زمان دشوار است."]]','ir0',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:consume','consume','v','مصرف کردن','/kənˈsuːm/ · use','The plants became food for the humans to consume.','[["The plants became food for the humans to consume.","گیاهان به غذایی برای مصرف انسان‌ها تبدیل شدند."],["Many consumers are not comfortable making purchases on the Internet.","بسیاری از مصرف کنندگان برای خرید از طریق اینترنت راحت نیستند."],["Cows consume a lot of grass.","گاوها علف زیادی مصرف می‌کنند."]]','ir0',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:data','data','n','داده‌ها، اطلاعات','/ˈdeɪtə, ˈdɑːtə/ · information or facts','Recent scientific data indicate that the Earth is warming.','[["Recent scientific data indicate that the Earth is warming.","داده‌های علمی اخیر نشان می‌دهند که زمین در حال گرم شدن است."],["The analysis was based on data collected in the field.","تجزیه و تحلیل بر اساس داده‌های جمع آوری شده در میدان انجام شد."],["The data show a clear pattern.","داده‌ها یک الگوی واضح را نشان می‌دهد."]]','ir0',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:derive','derive','v','به دست آوردن، مشتق شدن (از)','/dɪˈraɪv/ · get sth from sth','They believe that humans have not used the fuels that we derived from nature in a good way.','[["They believe that humans have not used the fuels that we derived from nature in a good way.","آن‌ها معتقدند انسان‌ها از سوخت‌هایی که از طبیعت به دست آورده‌ایم به‌درستی استفاده نکرده‌اند."],["Dairy products are derived from milk.","لبنیات از شیر گرفته می‌شود."]]','ir0',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:indicate','indicate','v','نشان دادن، حاکی بودن از','/ˈɪndɪkeɪt/ · show, demonstrate','Without any indication of danger, a giant ocean wave might suddenly sink boats.','[["Without any indication of danger, a giant ocean wave might suddenly sink boats.","بدون هیچ نشانه‌ای از خطر، ممکن بود یک موج عظیم اقیانوسی ناگهان قایق‌ها را غرق کند."],["Research indicates that teachers are dissatisfied with their salary.","تحقیقات نشان می‌دهد که معلمان از حقوق خود ناراضی هستند."],["The results indicate a strong link.","نتایج نشان دهنده یک پیوند قوی است."]]','ir0',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:obtain','obtain','v','به دست آوردن، کسب کردن','/əbˈteɪn/ · get, achieve','Rain filled lakes and rivers where they could obtain water to drink and catch fish to eat.','[["Rain filled lakes and rivers where they could obtain water to drink and catch fish to eat.","باران دریاچه‌ها و رودخانه‌ها را پر می‌کرد؛ جایی که می‌توانستند آب برای نوشیدن به دست آورند و ماهی بگیرند."],["You will need to obtain permission from the principal.","شما باید از مدیر اصلی اجازه بگیرید."]]','ir0',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:potential','potential','adj','بالقوه، احتمالی','/pəˈtenʃəl/ · possible','Homes were washed away when gentle rivers grew into potential killers.','[["Homes were washed away when gentle rivers grew into potential killers.","وقتی رودخانه‌های آرام به قاتلانی بالقوه تبدیل می‌شدند، خانه‌ها را آب می‌برد."],["potential customers","مشتریان بالقوه"],["This student has great potential.","این دانش آموز پتانسیل بالایی دارد."]]','ir0',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir0:source','source','n','منبع، سرچشمه','/sɔːrs/ · origin','The sun warmed them and was a source of light.','[["The sun warmed them and was a source of light.","خورشید آن‌ها را گرم می‌کرد و منبع نور بود."],["The sun is our source of energy.","خورشید منبع انرژی ماست."],["Tourism is the main source of income for the island.","گردشگری منبع اصلی درآمد این جزیره است."]]','ir0',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:alter','alter','v','تغییر دادن','/ˈɔːltər/ · change, adjust','This alteration made velocipedes much lighter, but riders still had to work hard to pedal just a short distance.','[["This alteration made velocipedes much lighter, but riders still had to work hard to pedal just a short distance.","این تغییر ولوسیپدها را بسیار سبک‌تر کرد، اما سوارکاران هنوز باید سخت رکاب می‌زدند تا فقط مسافتی کوتاه را بپیمایند."],["The place has altered in the 10 years since I left.","این مکان در 10 سالی که من ترک کردم تغییر کرده است."],["Climate change alters habitats.","تغییر اقلیم زیستگاه‌ها را تغییر می‌دهد."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:design','design','v','طراحی کردن','/dɪˈzaɪn/ · plan','So they designed a bicycle with a giant front wheel.','[["So they designed a bicycle with a giant front wheel.","پس دوچرخه‌ای با چرخ جلوی غول‌پیکر طراحی کردند."],["She designed a new logo for the company.","او لوگوی جدیدی برای این شرکت طراحی کرد."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:fee','fee','n','هزینه، کارمزد، شهریه','/fiː/ · price, charge','In fact, most riders preferred indoor tracks where they could rent a velocipede for a small fee and take riding lessons.','[["In fact, most riders preferred indoor tracks where they could rent a velocipede for a small fee and take riding lessons.","در واقع، بیشتر سوارکاران پیست‌های سرپوشیده را ترجیح می‌دادند که در آن‌جا می‌توانستند با پرداخت هزینه‌ای اندک ولوسیپد کرایه کنند و درس سوارکاری بگیرند."],["Tuition fees have now reached $9000 a year.","هزینه تحصیل در حال حاضر به 9000 دلار در سال رسیده است."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:framework','framework','n','چارچوب، ساختار','/ˈfreɪmwɜːk/ · structure','The frameworks were made of solid steel tubes, and the wooden wheels were covered with steel.','[["The frameworks were made of solid steel tubes, and the wooden wheels were covered with steel.","بدنه‌ها از لوله‌های فولادی توپر ساخته می‌شدند و چرخ‌های چوبی با فولاد پوشانده می‌شدند."],["This paper provides a framework for future research.","این مقاله چارچوبی برای تحقیقات آتی ارائه می‌دهد."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:individual','individual','n','فرد؛ فردی، شخصی','/ˌɪndəˈvɪdʒuəl/ · n., adj. · belonging to one person','The bicycle was not invented by one individual or in one country.','[["The bicycle was not invented by one individual or in one country.","دوچرخه را یک فرد یا یک کشور اختراع نکرد."],["The competition is open to both teams and individuals.","شرکت در این مسابقات به دو صورت تیمی و انفرادی آزاد است."],["Every individual has the right to education.","هر فردی حق تحصیل دارد."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:inherent','inherent','adj','ذاتی، درونی','/ɪnˈherənt/ · intrinsic, innate','Despite this inherent danger, “high wheelers” became very popular in England.','[["Despite this inherent danger, “high wheelers” became very popular in England.","با وجود این خطر ذاتی، «چرخ‌بلندها» در انگلستان بسیار محبوب شدند."],["Every business has its own inherent risks.","هر کسب و کاری خطرات ذاتی خود را دارد."],["There are risks inherent in any business.","خطرات ذاتی در هر کسب و کاری وجود دارد."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:injure','injure','v','مجروح کردن، آسیب زدن','/ˈɪndʒə(r)/ · to hurt a person or animal physically','This meant they were in danger of falling off the bicycle and injuring themselves if they lost their balance.','[["This meant they were in danger of falling off the bicycle and injuring themselves if they lost their balance.","این یعنی اگر تعادلشان را از دست می‌دادند، در خطر افتادن از دوچرخه و آسیب دیدن بودند."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:job','job','n','شغل، کار','/dʒɑːb/ · regular paid work','People didn’t ride velocipedes to the market or to their jobs.','[["People didn’t ride velocipedes to the market or to their jobs.","مردم با ولوسیپد به بازار یا سر کارشان نمی‌رفتند."],["It''s a temporary job, but I''m hoping it will be made permanent.","این یک کار موقت است، اما امیدوارم دائمی شود."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:minimize','minimize','v','به حداقل رساندن','/ˈmɪnɪmaɪz/ · reduced to the smallest size','Because the new safety bicycle minimized the dangers inherent in bicycle riding, more and more people began using bicycles in their daily activities.','[["Because the new safety bicycle minimized the dangers inherent in bicycle riding, more and more people began using bicycles in their daily activities.","از آن‌جا که دوچرخهٔ ایمنِ جدید خطرات ذاتی دوچرخه‌سواری را به حداقل رساند، مردم بیشتر و بیشتری در کارهای روزانه‌شان از دوچرخه استفاده کردند."],["The aim is to minimize costs.","هدف به حداقل رساندن هزینه‌ها است."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:overseas','overseas','adj','خارجی، ماورای دریا','/ˌəʊvərˈsiːz/ · abroad, foreign','Around 1870, American manufacturers saw that velocipedes were very popular overseas.','[["Around 1870, American manufacturers saw that velocipedes were very popular overseas.","در حدود سال ۱۸۷۰، تولیدکنندگان آمریکایی دیدند که ولوسیپدها در خارج از کشور بسیار محبوب‌اند."],["There are a lot of overseas students in Cambridge.","تعداد زیادی از دانشجویان خارج از کشور در کمبریج وجود دارد."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:primary','primary','adj','اصلی، اولیه','/ˈpraɪməri/ · main','Its primary purpose was to help the rider balance.','[["Its primary purpose was to help the rider balance.","هدف اصلی آن کمک به حفظ تعادل سوارکار بود."],["Their primary objective is to make money.","هدف اصلی آنها کسب درآمد است."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:revolution','revolution','n','انقلاب','/ˌrevəˈluːʃn/ · complete change, revolt','By the end of those 100 years, bicycles had revolutionized the way people traveled from place to place.','[["By the end of those 100 years, bicycles had revolutionized the way people traveled from place to place.","تا پایان آن ۱۰۰ سال، دوچرخه‌ها شیوهٔ رفت‌وآمد مردم را دگرگون کرده بودند."],["The king knew that there was a threat of revolution.","شاه می‌دانست که خطر انقلاب وجود دارد."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:subsequent','subsequent','adj','بعدی، متعاقب','/ˈsʌbsɪkwənt/ · next, later','A subsequent change by British engineers altered the wheels to make pedaling more efficient.','[["A subsequent change by British engineers altered the wheels to make pedaling more efficient.","تغییر بعدیِ مهندسان بریتانیایی چرخ‌ها را طوری عوض کرد که رکاب زدن کارآمدتر شود."],["Subsequently, the drug was found to cause cancer.","پس از آن مشخص شد که این دارو باعث سرطان می‌شود."],["Subsequent studies confirmed the result.","مطالعات بعدی نتیجه را تایید کرد."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:substitute','substitute','n','جایگزین، جانشین','a person or thing that takes the place of another','They substituted a small wheel for the giant front wheel and put the driving mechanism in a larger rear wheel.','[["They substituted a small wheel for the giant front wheel and put the driving mechanism in a larger rear wheel.","آن‌ها چرخ کوچکی را جایگزین چرخ جلوی غول‌پیکر کردند و سازوکار حرکت را در چرخ عقبِ بزرگ‌تر قرار دادند."],["Honey can be used as a substitute for sugar.","می‌توان از عسل به عنوان جایگزین شکر استفاده کرد."],["There is no substitute for hard work.","هیچ جایگزینی برای کار سخت وجود ندارد."]]','ir1',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:access','access','n','دسترسی','/ˈækses/ · right to use something','Unfortunately, many people live in far-away villages without access to quick medical care.','[["Unfortunately, many people live in far-away villages without access to quick medical care.","متأسفانه، بسیاری از مردم در روستاهای دورافتاده و بدون دسترسی به مراقبت پزشکی سریع زندگی می‌کنند."],["High-speed internet access has become a necessity.","دسترسی به اینترنت پرسرعت به یک ضرورت تبدیل شده است."],["Many villages still lack access to clean water.","بسیاری از روستاها هنوز به آب سالم دسترسی ندارند."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:accompany','accompany','v','همراهی کردن','/əˈkʌmpəni/ · go with sb, escort','Nausea and vomiting often accompany these symptoms.','[["Nausea and vomiting often accompany these symptoms.","حالت تهوع و استفراغ اغلب همراه این علائم است."],["Children under 14 must be accompanied by an adult.","کودکان زیر 14 سال باید با یک بزرگسال همراه باشند."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:conflict','conflict','n','تعارض، درگیری','/ˈkɒnflɪkt/ · opposition','Their old beliefs about illness may conflict with modern attempts to cure or prevent malaria.','[["Their old beliefs about illness may conflict with modern attempts to cure or prevent malaria.","باورهای قدیمی آن‌ها دربارهٔ بیماری ممکن است با تلاش‌های مدرن برای درمان یا پیشگیری از مالاریا در تعارض باشد."],["Normal kids who are in conflict with their parents.","بچه‌های عادی که با والدین خود در تعارض هستند."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:cooperate','cooperate','v','همکاری کردن','/kəʊˈɒpəreɪt/ · to work together toward the same goal','Some people may be unwilling to cooperate with government efforts to help them.','[["Some people may be unwilling to cooperate with government efforts to help them.","برخی مردم ممکن است تمایلی به همکاری با تلاش‌های دولت برای کمک به آن‌ها نداشته باشند."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:decline','decline','n','کاهش؛ کاهش یافتن','/dɪˈklaɪn/ · n., v. · decrease','Another problem is that the ability of quinine (the primary medicine used against malaria) to kill parasites has declined over time.','[["Another problem is that the ability of quinine (the primary medicine used against malaria) to kill parasites has declined over time.","مشکل دیگر این است که توانایی کینین (داروی اصلی ضد مالاریا) در کشتن انگل‌ها به مرور زمان کاهش یافته است."],["There has been a decline in the size of families.","تعداد خانواده‌ها کاهش یافته است."],["The number of visitors declined in 2020.","تعداد بازدیدکنندگان در سال 2020 کاهش یافت."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:implement','implement','v','اجرا کردن، پیاده‌سازی کردن','/ˈɪmpləment/ · do, carry out','It is very difficult, however, to implement these plans.','[["It is very difficult, however, to implement these plans.","با این حال، اجرای این برنامه‌ها بسیار دشوار است."],["We have decided to implement the committee''s recommendations in full.","ما تصمیم گرفته ایم که توصیه‌های کمیته را به طور کامل اجرا کنیم."],["The policy was implemented in 2019.","این سیاست در سال 2019 اجرا شد."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:intense','intense','adj','شدید','very strong','The place most intensely affected by malaria is Africa south of the Sahara Desert.','[["The place most intensely affected by malaria is Africa south of the Sahara Desert.","جایی که بیش از همه به‌شدت تحت تأثیر مالاریا قرار دارد، آفریقای جنوب صحرای بزرگ است."],["The heat was intense.","گرما شدید بود."],["The heat in the desert was intense.","گرمای بیابان شدید بود."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:labor','labor','n','کار، نیروی کار؛ زحمت کشیدن','/ˈleɪbər/ · n., v. · work, worker','They may not have the money to buy insect poisons and pay a labor force to spray regularly.','[["They may not have the money to buy insect poisons and pay a labor force to spray regularly.","ممکن است پول خرید سم حشره‌کش و پرداخت دستمزد نیروی کار برای سم‌پاشی منظم را نداشته باشند."],["Many women do hard manual labour.","بسیاری از زنان کارهای یدی سخت انجام می‌دهند."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:medical','medical','adj','پزشکی','/ˈmedɪkl/ · relating to the study of medicine','Becoming infected with malaria is a medical emergency.','[["Becoming infected with malaria is a medical emergency.","مبتلا شدن به مالاریا یک وضعیت اورژانسی پزشکی است."],["The injury required urgent medical attention.","جراحت نیاز به مراقبت فوری پزشکی داشت."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:ministry','ministry','n','وزارتخانه','/ˈmɪnɪstri/ · government department','Health ministries may not have the money to build clinics or hire trained medical practitioners.','[["Health ministries may not have the money to build clinics or hire trained medical practitioners.","وزارتخانه‌های بهداشت ممکن است پول ساخت درمانگاه یا استخدام پزشکان آموزش‌دیده را نداشته باشند."],["the ministry of Defense","وزارت دفاع"]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:occur','occur','v','رخ دادن، اتفاق افتادن','/əˈkɜːr/ · happen','It occurs mostly in tropical and subtropical parts of the world, including parts of Africa, Asia, South America, Central America, and the Middle East.','[["It occurs mostly in tropical and subtropical parts of the world, including parts of Africa, Asia, South America, Central America, and the Middle East.","این بیماری بیشتر در مناطق گرمسیری و نیمه‌گرمسیری جهان، از جمله بخش‌هایی از آفریقا، آسیا، آمریکای جنوبی، آمریکای مرکزی و خاورمیانه رخ می‌دهد."],["The disease tends to occur in children under five.","این بیماری بیشتر در کودکان زیر پنج سال رخ می‌دهد."],["Earthquakes occur along fault lines.","زمین لرزه‌ها در امتداد خطوط گسل رخ می‌دهند."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:practitioner','practitioner','n','متخصص شاغل (پزشک یا وکیل)','/prækˈtɪʃənər/ · sb who works as a doctor or lawyer','Health ministries may not have the money to build clinics or hire trained medical practitioners.','[["Health ministries may not have the money to build clinics or hire trained medical practitioners.","وزارتخانه‌های بهداشت ممکن است پول ساخت درمانگاه یا استخدام پزشکان آموزش‌دیده را نداشته باشند."],["Patients are treated by skilled practitioners.","بیماران توسط پزشکان ماهر درمان می‌شوند."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:priority','priority','n','اولویت','/praɪˈɔːrəti/ · greater importance','Immediate medical treatment must be a priority for people who are infected.','[["Immediate medical treatment must be a priority for people who are infected.","درمان پزشکی فوری باید برای افراد مبتلا در اولویت باشد."],["Education is a top priority.","آموزش در اولویت است."],["Safety is our top priority.","ایمنی اولویت اصلی ماست."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:reside','reside','v','سکونت داشتن، اقامت داشتن','/rɪˈzaɪd/ · to live in a particular place','These parasites reside in the bodies of Anopheles mosquitoes.','[["These parasites reside in the bodies of Anopheles mosquitoes.","این انگل‌ها در بدن پشه‌های آنوفل زندگی می‌کنند."]]','ir1',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:administrate','administrate','v','اداره کردن، مدیریت کردن','/ədˈmɪnɪstreɪt/ · to manage or run an organization','A survey administrated by the above consultants asked English speakers about their reactions to various letters of the alphabet.','[["A survey administrated by the above consultants asked English speakers about their reactions to various letters of the alphabet.","در نظرسنجی‌ای که مشاوران یادشده اجرا کردند، از انگلیسی‌زبانان دربارهٔ واکنششان به حروف مختلف الفبا پرسیده شد."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:channel','channel','n','کانال، مجرا','/ˈtʃænl/ · canal','In short, the goal of marketing is to channel a shopper’s choices toward a single, specific product.','[["In short, the goal of marketing is to channel a shopper’s choices toward a single, specific product.","به‌طور خلاصه، هدف بازاریابی این است که انتخاب‌های خریدار را به سمت یک محصول واحد و مشخص هدایت کند."],["the river is confined in a narrow channel","رودخانه در یک کانال باریک محدود شده است"]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:convince','convince','v','متقاعد کردن','/kənˈvɪns/ · persuade, induce','Marketers use strategies such as attractive packaging, catchy slogans, and other clever ways to convince consumers to buy their product.','[["Marketers use strategies such as attractive packaging, catchy slogans, and other clever ways to convince consumers to buy their product.","بازاریاب‌ها از راهبردهایی مانند بسته‌بندی جذاب، شعارهای گیرا و دیگر روش‌های زیرکانه برای متقاعد کردن مصرف‌کنندگان به خرید محصولشان استفاده می‌کنند."],["I am convinced the war will be over in a month.","من مطمئن هستم که جنگ تا یک ماه دیگر تمام خواهد شد."],["She convinced me to join the club.","او مرا متقاعد کرد که به باشگاه بپیوندم."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:domestic','domestic','adj','داخلی؛ خانگی','/dəˈmestɪk/ · family, internal','The team must also decide if the focus will be on domestic sales or if the baby food will be exported to foreign countries.','[["The team must also decide if the focus will be on domestic sales or if the baby food will be exported to foreign countries.","تیم همچنین باید تصمیم بگیرد که تمرکز بر فروش داخلی باشد یا غذای کودک به کشورهای خارجی صادر شود."],["Unfortunately his domestic life wasn''t very happy.","متأسفانه زندگی خانگی او چندان شاد نبود."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:explicit','explicit','adj','صریح، روشن','/ɪkˈsplɪsɪt/ · clear','This slogan has both an explicit and an implicit message.','[["This slogan has both an explicit and an implicit message.","این شعار هم پیامی صریح و هم پیامی ضمنی دارد."],["He was quite explicit as to what he expected us to do for him.","او کاملاً صریح بود که انتظار داشت ما برای او چه کاری انجام دهیم."],["The instructions were explicit.","دستورالعمل‌ها صریح بود."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:export','export','n','صادرات؛ صادر کردن','/ˈekspɔːt/ · n., v. · sell goods to another country · ≠ import','The team must also decide if the focus will be on domestic sales or if the baby food will be exported to foreign countries.','[["The team must also decide if the focus will be on domestic sales or if the baby food will be exported to foreign countries.","تیم همچنین باید تصمیم بگیرد که تمرکز بر فروش داخلی باشد یا غذای کودک به کشورهای خارجی صادر شود."],["Wheat is one of the country''s chief exports.","گندم یکی از صادرات عمده این کشور است."],["Iran exports pistachios to many countries.","ایران به بسیاری از کشورها پسته صادر می‌کند."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:implicit','implicit','adj','ضمنی، تلویحی','/ɪmˈplɪsɪt/ · indirect, hidden','This slogan has both an explicit and an implicit message.','[["This slogan has both an explicit and an implicit message.","این شعار هم پیامی صریح و هم پیامی ضمنی دارد."],["Her words contained an implicit threat.","سخنان او حاوی یک تهدید ضمنی بود."],["There was an implicit criticism in his words.","انتقاد تلویحی در سخنان او بود."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:income','income','n','درآمد','/ˈɪŋkʌm/ · money you earn from working','Factors such as the sex, age, education, and income of future customers are considered.','[["Factors such as the sex, age, education, and income of future customers are considered.","عواملی مانند جنسیت، سن، تحصیلات و درآمد مشتریان آینده در نظر گرفته می‌شود."],["He earns a good income as a consultant.","او به عنوان مشاور درآمد خوبی کسب می‌کند."],["Average income has increased.","درآمد متوسط ​​افزایش یافته است."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:innovate','innovate','v','نوآوری کردن','/ˈɪnəveɪt/ · to introduce new ideas or methods','Suppose that a company has developed an innovative new product: a powder made from dried fruit.','[["Suppose that a company has developed an innovative new product: a powder made from dried fruit.","فرض کنید شرکتی محصول نوآورانهٔ جدیدی ساخته است: پودری از میوهٔ خشک‌شده."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:invoke','invoke','v','استناد کردن به؛ برانگیختن','/ɪnˈvəʊk/ · implement, evoke','Maybe the ads will invoke the authority of a famous baby doctor to emphasize the health appeal.','[["Maybe the ads will invoke the authority of a famous baby doctor to emphasize the health appeal.","شاید آگهی‌ها به اعتبار یک پزشک کودکان مشهور استناد کنند تا بر جذابیت سلامت‌محور محصول تأکید کنند."],["The UN threatened to invoke economic sanctions.","سازمان ملل تهدید به اعمال تحریم‌های اقتصادی کرد."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:publish','publish','v','منتشر کردن، چاپ کردن','/ˈpʌblɪʃ/ · print','They must decide where to publish advertisements and what the ads should say.','[["They must decide where to publish advertisements and what the ads should say.","آن‌ها باید تصمیم بگیرند آگهی‌ها را کجا منتشر کنند و در آگهی‌ها چه گفته شود."],["The first edition was published in 1765.","اولین نسخه در سال 1765 منتشر شد."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:sector','sector','n','بخش (اقتصادی)، حوزه','/ˈsektər/ · part of an area of business','Then, a marketing team designs a plan aimed at a specific sector of the population, the group that they think is most likely to buy the product.','[["Then, a marketing team designs a plan aimed at a specific sector of the population, the group that they think is most likely to buy the product.","سپس تیم بازاریابی برنامه‌ای طراحی می‌کند که بخش خاصی از جمعیت را هدف می‌گیرد؛ گروهی که فکر می‌کنند به احتمال زیاد محصول را می‌خرند."],["the agricultural sector of the economy","بخش کشاورزی اقتصاد"]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:sex','sex','n','جنسیت','/seks/ · the state of being male or female','Factors such as the sex, age, education, and income of future customers are considered.','[["Factors such as the sex, age, education, and income of future customers are considered.","عواملی مانند جنسیت، سن، تحصیلات و درآمد مشتریان آینده در نظر گرفته می‌شود."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:survey','survey','n','نظرسنجی، بررسی؛ بررسی کردن','/ˈsɜːrveɪ/ · n., v. · poll','A marketing plan often begins with a survey to determine who is most likely to buy a certain type of product.','[["A marketing plan often begins with a survey to determine who is most likely to buy a certain type of product.","یک برنامهٔ بازاریابی اغلب با یک نظرسنجی آغاز می‌شود تا مشخص شود چه کسانی به احتمال زیاد نوع خاصی از محصول را می‌خرند."],["We conducted a survey of parents in the village.","ما یک نظرسنجی از والدین در روستا انجام دادیم."],["A survey of 500 people was carried out.","نظرسنجی از 500 نفر انجام شد."]]','ir1',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:acquire','acquire','v','کسب کردن','to gain or obtain','The more umbrellas a ruler acquired, the more he impressed others; and, by analogy, the bigger his umbrellas, the more power the owner appeared to have.','[["The more umbrellas a ruler acquired, the more he impressed others; and, by analogy, the bigger his umbrellas, the more power the owner appeared to have.","هرچه فرمانروا چترهای بیشتری به دست می‌آورد، دیگران را بیشتر تحت تأثیر قرار می‌داد؛ و به همین قیاس، هرچه چترهایش بزرگ‌تر بود، صاحبش قدرتمندتر به نظر می‌رسید."],["Children acquire languages easily.","کودکان به راحتی زبان می‌آموزند."],["She acquired a good knowledge of English while living in London.","او در زمان زندگی در لندن دانش خوبی از زبان انگلیسی به دست آورد."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:ambiguous','ambiguous','adj','مبهم، دوپهلو','/æmˈbɪɡjuəs/ · unclear, obscure','If we give each a title, the ambiguous story becomes easier to understand.','[["If we give each a title, the ambiguous story becomes easier to understand.","اگر به هرکدام عنوانی بدهیم، داستانِ مبهم آسان‌تر فهمیده می‌شود."],["Their position in society remains ambiguous.","جایگاه آنها در جامعه همچنان مبهم است."],["The question was ambiguous.","سوال مبهم بود."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:analogy','analogy','n','قیاس، تشبیه','≈ comparison, parallel — Cambridge 13 · Test 4 · Passage 3: Psychology of Creativity','These include the royal male titles king, emperor, and sultan and their analogous female titles queen, empress, and sultana.','[["These include the royal male titles king, emperor, and sultan and their analogous female titles queen, empress, and sultana.","این‌ها شامل عنوان‌های سلطنتی مردانه مانند پادشاه، امپراتور و سلطان و عنوان‌های زنانهٔ متناظرشان یعنی ملکه، امپراتریس و سلطانه است."],["Scientists use analogy to explain complex ideas.","دانشمندان از قیاس برای توضیح ایده‌های پیچیده استفاده می‌کنند."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:civil','civil','adj','مدنی، غیرنظامی؛ مؤدب','/ˈsɪvl/ · polite, nonmilitary','Every civil leader has a title, too, though these vary somewhat depending on a country’s system of government.','[["Every civil leader has a title, too, though these vary somewhat depending on a country’s system of government.","هر رهبر مدنی نیز عنوانی دارد، هرچند این عنوان‌ها بسته به نظام حکومتی هر کشور تا حدی متفاوت‌اند."],["She was barely civil to me.","او به سختی نسبت به من متمدن بود."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:constitute','constitute','v','تشکیل دادن، به شمار آمدن','/ˈkɒnstɪtjuːt/ · to form or make up; to be considered as','A given name plus the inherited title usually constitute their public names, such as King Faisal or Queen Elizabeth.','[["A given name plus the inherited title usually constitute their public names, such as King Faisal or Queen Elizabeth.","یک نام کوچک به‌علاوهٔ عنوان موروثی معمولاً نام رسمی آن‌ها را تشکیل می‌دهد، مانند ملک فیصل یا ملکه الیزابت."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:context','context','n','زمینه، بافت، شرایط','/ˈkɒntekst/ · situation','The title engineer defines his status within the context of employment.','[["The title engineer defines his status within the context of employment.","عنوان «مهندس» جایگاه او را در چارچوب شغلی‌اش مشخص می‌کند."],["the political context of the election","زمینه سیاسی انتخابات"]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:convene','convene','v','تشکیل جلسه دادن، گرد هم آمدن','/kənˈviːn/ · to come or bring together for a meeting','When official meetings convene, the leaders are addressed in a formal style, such as Madam President or Governor Ramos.','[["When official meetings convene, the leaders are addressed in a formal style, such as Madam President or Governor Ramos.","وقتی جلسات رسمی تشکیل می‌شوند، رهبران با شیوه‌ای رسمی خطاب می‌شوند، مانند «خانم رئیس‌جمهور» یا «فرماندار راموس»."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:differentiate','differentiate','v','متمایز کردن، فرق گذاشتن','/ˌdɪfəˈrenʃieɪt/ · distinguish, discriminate','Within a group, titles help differentiate one person from another.','[["Within a group, titles help differentiate one person from another.","در یک گروه، عنوان‌ها به متمایز کردن افراد از یکدیگر کمک می‌کنند."],["It''s important to differentiate between fact and opinion.","مهم است که بین واقعیت و نظر تفاوت قائل شویم."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:index','index','n','فهرست، نمایه؛ شاخص','/ˈɪndeks/ · list, directory','A person''s job title also serves as an index (or measure) of his or her status within the company.','[["A person''s job title also serves as an index (or measure) of his or her status within the company.","عنوان شغلی یک فرد نیز شاخصی (یا معیاری) از جایگاه او در شرکت است."],["Try looking up ''heart disease'' in the index.","سعی کنید «بیماری قلبی» را در فهرست جستجو کنید."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:integral','integral','adj','جدایی‌ناپذیر، ضروری','/ˈɪntɪɡrəl, ɪnˈteɡrəl/ · vital, essential','Each person is an integral part of many different groups, so each person has many titles.','[["Each person is an integral part of many different groups, so each person has many titles.","هر فرد بخشی جدایی‌ناپذیر از گروه‌های مختلف بسیاری است، بنابراین هر فرد عنوان‌های زیادی دارد."],["Games are an integral part of the school''s curriculum.","بازی بخشی جدایی ناپذیر از برنامه درسی مدرسه است."],["Sport is an integral part of school life.","ورزش بخشی جدایی ناپذیر از زندگی مدرسه است."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:military','military','adj','نظامی','/ˈmɪləteri/ · related to the army','Titles are especially important in the military, where authority is channeled from top to bottom via a strict chain of command.','[["Titles are especially important in the military, where authority is channeled from top to bottom via a strict chain of command.","عنوان‌ها به‌ویژه در ارتش مهم‌اند؛ جایی که اقتدار از طریق زنجیرهٔ فرماندهیِ سخت‌گیرانه از بالا به پایین منتقل می‌شود."],["We may have to take military action.","ممکن است مجبور به اقدام نظامی شویم."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:somewhat','somewhat','adv','تا حدی، کمی','/ˈsʌmwʌt/ · to some extent, slightly','Every civil leader has a title, too, though these vary somewhat depending on a country’s system of government.','[["Every civil leader has a title, too, though these vary somewhat depending on a country’s system of government.","هر رهبر مدنی نیز عنوانی دارد، هرچند این عنوان‌ها بسته به نظام حکومتی هر کشور تا حدی متفاوت‌اند."],["She is somewhat lazy.","او تا حدودی تنبل است."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:style','style','n','سبک، شیوه','/staɪl/ · mode, fashion','When official meetings convene, the leaders are addressed in a formal style, such as Madam President or Governor Ramos.','[["When official meetings convene, the leaders are addressed in a formal style, such as Madam President or Governor Ramos.","وقتی جلسات رسمی تشکیل می‌شوند، رهبران با شیوه‌ای رسمی خطاب می‌شوند، مانند «خانم رئیس‌جمهور» یا «فرماندار راموس»."],["The car is available in several different styles.","این خودرو در چندین سبک مختلف موجود است."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:whereby','whereby','adv','که به‌وسیلهٔ آن، به موجب آن','/werˈbaɪ/ · by which','Titles also provide guidelines whereby people know how to address others.','[["Titles also provide guidelines whereby people know how to address others.","عنوان‌ها همچنین رهنمودهایی فراهم می‌کنند که به‌واسطهٔ آن‌ها مردم می‌دانند دیگران را چگونه خطاب کنند."],["A plan whereby we can make lots of money.","طرحی که به موجب آن بتوانیم پول زیادی به دست آوریم."]]','ir1',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:attain','attain','v','دست یافتن، رسیدن به','/əˈteɪn/ · succeed in doing sth, accomplish','It is about attaining something that is valued by others.','[["It is about attaining something that is valued by others.","موضوع، دستیابی به چیزی است که دیگران برایش ارزش قائل‌اند."],["He has attained the highest grade in his music exams.","او بالاترین نمره را در امتحانات موسیقی خود کسب کرده است."],["Few students attain a perfect score.","تعداد کمی از دانش آموزان به نمره کامل می‌رسند."]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:aware','aware','adj','آگاه، مطلع','/əˈwer/ · conscious, informed','If parents are aware that a lack of ambition is common in teenagers, they may be able to minimize it by providing positive learning experiences in the early years.','[["If parents are aware that a lack of ambition is common in teenagers, they may be able to minimize it by providing positive learning experiences in the early years.","اگر والدین بدانند که کمبود جاه‌طلبی در نوجوانان رایج است، شاید بتوانند با فراهم کردن تجربه‌های یادگیری مثبت در سال‌های نخست، آن را به حداقل برسانند."],["The children are aware of the danger of taking drugs.","کودکان از خطر مصرف مواد آگاه هستند."],["Are you aware of the risks?","آیا از خطرات آن آگاه هستید؟"]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:coincide','coincide','v','همزمان شدن، مصادف شدن','/ˌkəʊɪnˈsaɪd/ · happen at the same time','It is not a coincidence that successful parents tend to raise successful children.','[["It is not a coincidence that successful parents tend to raise successful children.","تصادفی نیست که والدین موفق معمولاً فرزندان موفقی بار می‌آورند."],["The goals of the business partners coincide.","اهداف شرکای تجاری منطبق است."],["The festival coincides with the harvest.","جشنواره همزمان با برداشت محصول است."]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:colleague','colleague','n','همکار','/ˈkɑːliːɡ/ · coworker','They seek assistance from anyone who might further their chances to succeed, including family members, friends, coaches, and colleagues.','[["They seek assistance from anyone who might further their chances to succeed, including family members, friends, coaches, and colleagues.","آن‌ها از هر کسی که بتواند شانس موفقیتشان را بیشتر کند کمک می‌گیرند، از جمله اعضای خانواده، دوستان، مربیان و همکاران."],["A colleague of mine will be speaking at the conference.","یکی از همکاران من در کنفرانس سخنرانی خواهد کرد."]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:demonstrate','demonstrate','v','نشان دادن، اثبات کردن','/ˈdemənstreɪt/ · show','Consider the ambition that babies demonstrate as they try to sit up, crawl, and walk.','[["Consider the ambition that babies demonstrate as they try to sit up, crawl, and walk.","جاه‌طلبی‌ای را در نظر بگیرید که نوزادان هنگام تلاش برای نشستن، چهار دست و پا رفتن و راه رفتن نشان می‌دهند."],["These figures clearly demonstrate the size of the economic problem.","این ارقام به وضوح اندازه مشکل اقتصادی را نشان می‌دهد."],["The study demonstrates the value of exercise.","این مطالعه ارزش ورزش را نشان می‌دهد."]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:dominate','dominate','v','مسلط شدن، غالب بودن، تسلط داشتن','to control or have power over; to be the most important feature','With their eyes on the future, their goals dominate the choices they make.','[["With their eyes on the future, their goals dominate the choices they make.","با چشم دوختن به آینده، اهدافشان بر انتخاب‌هایشان چیره است."],["Large companies dominate the market.","شرکت‌های بزرگ بر بازار تسلط دارند."],["The castle dominates the town.","قلعه بر شهر مسلط است."]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:dynamic','dynamic','adj','پویا','/daɪˈnæmɪk/ · continuously moving or changing # static','Despite their backgrounds, it is people with dynamic personalities who are most likely to succeed.','[["Despite their backgrounds, it is people with dynamic personalities who are most likely to succeed.","فارغ از پیشینه‌شان، این افراد دارای شخصیت پویا هستند که بیشترین احتمال موفقیت را دارند."],["dynamic and ambitious people.","افراد پویا و جاه طلب"]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:exploit','exploit','v','بهره‌برداری کردن؛ استثمار کردن','/ɪkˈsplɔɪt/ · take advantage of, abuse','They exploit—that is, take advantage of—opportunities to broaden their knowledge through experience and observation.','[["They exploit—that is, take advantage of—opportunities to broaden their knowledge through experience and observation.","آن‌ها از فرصت‌ها بهره‌برداری می‌کنند — یعنی از آن‌ها استفاده می‌کنند — تا دانش خود را از راه تجربه و مشاهده گسترش دهند."],["the exploitation of migrant workers","استثمار کارگران مهاجر"],["Some firms exploit cheap labor.","برخی از شرکت‌ها از نیروی کار ارزان بهره برداری می‌کنند."]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:generate','generate','v','تولید کردن، ایجاد کردن','/ˈdʒenəreɪt/ · produce','For each person it will be different, though, because individuals generate their own definitions of success.','[["For each person it will be different, though, because individuals generate their own definitions of success.","با این حال، برای هر کس متفاوت خواهد بود، چون افراد تعریف‌های خودشان را از موفقیت می‌سازند."],["The wind turbines are used to generate electricity.","از توربین‌های بادی برای تولید برق استفاده می‌شود."],["The new factory will generate hundreds of jobs.","کارخانه جدید صدها شغل ایجاد خواهد کرد."]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:inhibit','inhibit','v','مانع شدن، بازداشتن','/ɪnˈhɪbɪt/ · prevent, prohibit','During the teen years, however, a fear of failure or a fear of being laughed at by others for trying to “be somebody” may inhibit, or stop, their persistence.','[["During the teen years, however, a fear of failure or a fear of being laughed at by others for trying to “be somebody” may inhibit, or stop, their persistence.","اما در سال‌های نوجوانی، ترس از شکست یا ترس از تمسخر دیگران به خاطر تلاش برای «کسی شدن» ممکن است پشتکارشان را مهار کند یا متوقف سازد."],["the obstacles which inhibit change","موانعی که مانع از تغییر می‌شوند"]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:media','media','n','رسانه‌ها','/ˈmiːdiə/ · press, mass media','That’s because stories in the media about successful business executives, professional golfers, glamorous movie stars, best-selling authors, and powerful politicians lead us to believe that only a few special people are successful.','[["That’s because stories in the media about successful business executives, professional golfers, glamorous movie stars, best-selling authors, and powerful politicians lead us to believe that only a few special people are successful.","دلیلش این است که داستان‌های رسانه‌ها دربارهٔ مدیران موفق، گلف‌بازان حرفه‌ای، ستارگان پرزرق‌وبرق سینما، نویسندگان پرفروش و سیاستمداران قدرتمند ما را به این باور می‌رسانند که فقط عدهٔ اندکی از افراد خاص موفق‌اند."],["The media are covering the speech tonight.","رسانه‌ها این سخنرانی امشب را پوشش می‌دهند."],["The media has a strong influence on opinion.","رسانه‌ها تاثیر زیادی بر افکار دارند."]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:positive','positive','adj','مثبت','/ˈpɒzətɪv/ · good, hopeful; certain · ≠ negative','If parents are aware that a lack of ambition is common in teenagers, they may be able to minimize it by providing positive learning experiences in the early years.','[["If parents are aware that a lack of ambition is common in teenagers, they may be able to minimize it by providing positive learning experiences in the early years.","اگر والدین بدانند که کمبود جاه‌طلبی در نوجوانان رایج است، شاید بتوانند با فراهم کردن تجربه‌های یادگیری مثبت در سال‌های نخست، آن را به حداقل برسانند."],["You''ve got to be more positive about your work.","شما باید در مورد کار خود مثبت‌تر باشید."]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:professional','professional','adj','حرفه‌ای، متخصص','/prəˈfeʃənl/ · expert','That’s because stories in the media about successful business executives, professional golfers, glamorous movie stars, best-selling authors, and powerful politicians lead us to believe that only a few special people are successful.','[["That’s because stories in the media about successful business executives, professional golfers, glamorous movie stars, best-selling authors, and powerful politicians lead us to believe that only a few special people are successful.","دلیلش این است که داستان‌های رسانه‌ها دربارهٔ مدیران موفق، گلف‌بازان حرفه‌ای، ستارگان پرزرق‌وبرق سینما، نویسندگان پرفروش و سیاستمداران قدرتمند ما را به این باور می‌رسانند که فقط عدهٔ اندکی از افراد خاص موفق‌اند."],["Their music is both memorable and professional.","موسیقی آنها هم خاطره انگیز و هم حرفه ای است."]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:role','role','n','نقش','/roʊl/ · part','Evidence suggests that both play a role in determining ambition.','[["Evidence suggests that both play a role in determining ambition.","شواهد نشان می‌دهد که هر دو در تعیین جاه‌طلبی نقش دارند."],["They want to limit the role of government.","آنها می‌خواهند نقش دولت را محدود کنند."]]','ir1',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:authority','authority','n','اقتدار، اختیار؛ مقامات، مسئولان','/əˈθɒrəti/ · power; people in charge','Authorities accused the servant of theft, and he confessed to the crime.','[["Authorities accused the servant of theft, and he confessed to the crime.","مقامات خدمتکار را به دزدی متهم کردند و او به جرم اعتراف کرد."],["The French authorities have refused to issue him a visa.","مقامات فرانسه از صدور ویزا برای او خودداری کرده اند."],["Local authorities closed the road.","مقامات محلی جاده را بستند."]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:conclude','conclude','v','نتیجه گرفتن','to decide after thinking','“Someone has been in here,” Susan concluded.','[["“Someone has been in here,” Susan concluded.","سوزان نتیجه گرفت: «کسی این‌جا بوده است.»"],["The researchers concluded that the drug works.","محققان به این نتیجه رسیدند که این دارو کار می‌کند."],["The researchers concluded that the drug was safe.","محققان به این نتیجه رسیدند که این دارو بی خطر است."]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:consult','consult','v','مشورت کردن، رجوع کردن به','/kənˈsʌlt/ · exchange views, confer','He consulted Eduard and Susan, but only the jewelry seemed to be missing.','[["He consulted Eduard and Susan, but only the jewelry seemed to be missing.","او با ادوارد و سوزان مشورت کرد، اما به نظر می‌رسید فقط جواهرات گم شده‌اند."],["I need to consult with my lawyer.","باید با وکیلم مشورت کنم"]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:contrary','contrary','adj','مخالف، متضاد','/ˈkɑːntreri/ · different, opposite','To the contrary, this thief seemed to know exactly where to find valuables.','[["To the contrary, this thief seemed to know exactly where to find valuables.","برعکس، به نظر می‌رسید این دزد دقیقاً می‌دانست اشیای قیمتی را کجا پیدا کند."],["Contrary to popular belief, many cats dislike milk.","برخلاف تصور رایج، بسیاری از گربه‌ها از شیر بیزارند."]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:detect','detect','v','کشف کردن، تشخیص دادن','/dɪˈtekt/ · discover, solve','She was told that a police detective would be at the site in a few minutes.','[["She was told that a police detective would be at the site in a few minutes.","به او گفته شد که یک کارآگاه پلیس تا چند دقیقهٔ دیگر در محل خواهد بود."],["the public can help the police to detect crime","مردم می‌توانند به پلیس برای کشف جرم کمک کنند"]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:establish','establish','v','تأسیس کردن، برقرار کردن','/ɪˈstæblɪʃ/ · set up, found','Subsequent tests done at a police laboratory established that the grass stains on the shirt matched the type of grass at the mansion.','[["Subsequent tests done at a police laboratory established that the grass stains on the shirt matched the type of grass at the mansion.","آزمایش‌های بعدی در آزمایشگاه پلیس ثابت کرد که لکه‌های چمن روی پیراهن با نوع چمن عمارت مطابقت دارد."],["The company was established in 1899.","این شرکت در سال 1899 تاسیس شد."]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:instance','instance','n','مورد، نمونه','/ˈɪnstəns/ · example','In each instance, the evidence pointed to the servant''s guilt.','[["In each instance, the evidence pointed to the servant''s guilt.","در هر مورد، شواهد به گناهکار بودن خدمتکار اشاره داشت."],["for instance","به عنوان مثال"]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:logic','logic','n','منطق','/ˈlɑːdʒɪk/ · a system of reasoning','It seemed logical that the thief knew the house.','[["It seemed logical that the thief knew the house.","منطقی به نظر می‌رسید که دزد خانه را می‌شناخته است."],["If you just use a little logic, you''ll see I''m right.","اگر فقط کمی از منطق استفاده کنید، متوجه می‌شوید که حق با من است."]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:motive','motive','n','انگیزه','/ˈməʊtɪv/ · a reason for doing something','What motive would they have for faking a theft?','[["What motive would they have for faking a theft?","آن‌ها چه انگیزه‌ای برای جعل یک سرقت داشتند؟"]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:panel','panel','n','هیئت، پنل؛ صفحه','/ˈpænl/ · a board; a group of experts','He pushed open a wall panel and used a code to open a hidden safe.','[["He pushed open a wall panel and used a code to open a hidden safe.","او یک صفحهٔ دیوار را به عقب هل داد و با یک رمز گاوصندوق پنهانی را باز کرد."],["The roof is covered with solar panels that absorb the sun''s rays.","سقف با پنل‌های خورشیدی پوشیده شده است که اشعه‌های خورشید را جذب می‌کند."]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:site','site','n','محل، مکان','/saɪt/ · place','She was told that a police detective would be at the site in a few minutes.','[["She was told that a police detective would be at the site in a few minutes.","به او گفته شد که یک کارآگاه پلیس تا چند دقیقهٔ دیگر در محل خواهد بود."],["Hard hats must be worn on the construction site.","کلاه‌های سخت باید در محل ساخت و ساز استفاده شود."]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:specific','specific','adj','خاص، مشخص، ویژه','/spəˈsɪfɪk/ · particular','He wanted to know the specific time they had returned home.','[["He wanted to know the specific time they had returned home.","او می‌خواست زمان دقیق بازگشت آن‌ها به خانه را بداند."],["Could you be more specific about what you''re looking for?","آیا می‌توانید در مورد آنچه به دنبال آن هستید دقیق‌تر بگویید؟"]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:tape','tape','n','نوار','/teɪp/ · cassette','They put these pieces of evidence into envelopes and taped them shut.','[["They put these pieces of evidence into envelopes and taped them shut.","آن‌ها این مدارک را در پاکت گذاشتند و با چسب بستند."],["Bring me a blank tape and I''ll record it for you.","یک نوار سفید برای من بیاور تا برایت ضبط کنم."]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:technical','technical','adj','فنی','/ˈteknɪkəl/ · relating to a complex process','Technically, Eduard was guilty, too, and he was sentenced to prison for his role in the crime.','[["Technically, Eduard was guilty, too, and he was sentenced to prison for his role in the crime.","از نظر فنی، ادوارد هم گناهکار بود و به خاطر نقشش در این جرم به زندان محکوم شد."],["Our staff will be available to give you technical support.","کارکنان ما برای ارائه پشتیبانی فنی به شما در دسترس خواهند بود."]]','ir1',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:abandon','abandon','v','رها کردن، ترک کردن','/əˈbændən/ · quit, leave, give up','Before abandoning their successful business, however, they decided to try a new system of preparing and serving food.','[["Before abandoning their successful business, however, they decided to try a new system of preparing and serving food.","اما پیش از کنار گذاشتن کسب‌وکار موفقشان، تصمیم گرفتند سیستم تازه‌ای برای آماده‌سازی و سرو غذا را امتحان کنند."],["How could she abandon her own child?","چگونه می‌توانست فرزند خود را رها کند؟"],["They abandoned the old car in the desert.","ماشین قدیمی را در بیابان رها کردند."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:acknowledge','acknowledge','v','تصدیق کردن، اذعان کردن','/əkˈnɒlɪdʒ/ · admit, recognize','He acknowledged that this new restaurant system was a good business model.','[["He acknowledged that this new restaurant system was a good business model.","او پذیرفت که این سیستم جدید رستوران، الگوی کسب‌وکار خوبی است."],["Claire acknowledged that she was guilty.","کلر اعتراف کرد که مقصر است."],["He acknowledged his mistake.","او به اشتباه خود اعتراف کرد."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:albeit','albeit','conj','اگرچه، هرچند','/ˌɔːlˈbiːɪt/ · although','Carl Karcher heard that a nearby restaurant was selling cheap, albeit top-grade hamburgers for 15 cents.','[["Carl Karcher heard that a nearby restaurant was selling cheap, albeit top-grade hamburgers for 15 cents.","کارل کارچر شنید که رستورانی در همان نزدیکی همبرگرهای ارزان، هرچند درجه‌یک، را به قیمت ۱۵ سنت می‌فروشد."],["He was making progress, albeit rather slowly.","او در حال پیشرفت بود، البته نسبتاً کند."],["It was a success, albeit a small one.","موفقیتی بود، هرچند کوچک."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:complement','complement','v','مکمل؛ تکمیل کردن','/ˈkɑːmplɪment/ · v., adj. · complete, accompany','These were complemented by new fast-food restaurants where travelers could eat a quick meal.','[["These were complemented by new fast-food restaurants where travelers could eat a quick meal.","رستوران‌های فست‌فود جدید، که مسافران می‌توانستند در آن‌ها غذایی سریع بخورند، مکمل این‌ها شدند."],["Fruit would be a good complement for this meal.","میوه مکمل خوبی برای این وعده غذایی خواهد بود."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:contemporary','contemporary','adj','معاصر، هم‌دوره','/kənˈtempəreri/ · belonging to the same time','Among the contemporary start-ups in the 1950s and 1960s were Burger King, Wendy''s, Domino’s Pizza, and Kentucky Fried Chicken (KFC).','[["Among the contemporary start-ups in the 1950s and 1960s were Burger King, Wendy''s, Domino’s Pizza, and Kentucky Fried Chicken (KFC).","از جمله کسب‌وکارهای نوپای هم‌دوره در دهه‌های ۱۹۵۰ و ۱۹۶۰ می‌توان به برگرکینگ، وندیز، دومینوز پیتزا و کنتاکی فرایدچیکن (KFC) اشاره کرد."],["He doesn''t like contemporary art.","او هنر معاصر را دوست ندارد."],["He was a contemporary of Shakespeare.","او معاصر شکسپیر بود."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:contrast','contrast','n','تضاد، تقابل؛ مقایسه کردن','/ˈkɒntrɑːst/ · n., v. · find the differences','Their remodeled restaurant contrasted with the original.','[["Their remodeled restaurant contrasted with the original.","رستوران بازسازی‌شدهٔ آن‌ها با رستوران اولیه تفاوت آشکاری داشت."],["Compare and contrast the two novels.","این دو رمان را با هم مقایسه و مقایسه کنید."],["In contrast, sales in Asia rose.","در مقابل، فروش در آسیا افزایش یافت."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:decade','decade','n','دهه','/ˈdekeɪd, deˈkeɪd/ · ten years','A decade later, there were nearly 3,000 restaurants in the McDonald’s restaurant chain, all owned by one corporation.','[["A decade later, there were nearly 3,000 restaurants in the McDonald’s restaurant chain, all owned by one corporation.","یک دهه بعد، نزدیک به ۳۰۰۰ رستوران در زنجیرهٔ مک‌دونالد وجود داشت که همه متعلق به یک شرکت بودند."],["The fourth decade of the nineteenth century","دهه چهارم قرن نوزدهم"],["The city has grown rapidly over the last decade.","این شهر در دهه گذشته به سرعت رشد کرده است."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:economy','economy','n','اقتصاد','the system of money and trade','One factor was that the U.S. economy was expanding.','[["One factor was that the U.S. economy was expanding.","یکی از عوامل این بود که اقتصاد آمریکا در حال گسترش بود."],["Tourism is vital to the economy.","گردشگری برای اقتصاد حیاتی است."],["Tourism is important for the local economy.","گردشگری برای اقتصاد محلی مهم است."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:expand','expand','v','گسترش دادن، گسترش یافتن','/ɪkˈspænd/ · grow, extend','One factor was that the U.S. economy was expanding.','[["One factor was that the U.S. economy was expanding.","یکی از عوامل این بود که اقتصاد آمریکا در حال گسترش بود."],["a period of rapid economic expansion","دوره رشد سریع اقتصادی"],["The company plans to expand overseas.","این شرکت قصد دارد در خارج از کشور گسترش یابد."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:generation','generation','n','نسل','/ˌdʒenəˈreɪʃn/ · same age group','The young people in the 1950s were an optimistic generation.','[["The young people in the 1950s were an optimistic generation.","جوانان دههٔ ۱۹۵۰ نسلی خوش‌بین بودند."],["My generation have grown up with the internet.","نسل من با اینترنت بزرگ شده است."],["The younger generation uses smartphones daily.","نسل جوان روزانه از گوشی‌های هوشمند استفاده می‌کند."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:grade','grade','n','درجه، رتبه؛ نمره','/ɡreɪd/ · level, rank','Carl Karcher heard that a nearby restaurant was selling cheap, albeit top-grade hamburgers for 15 cents.','[["Carl Karcher heard that a nearby restaurant was selling cheap, albeit top-grade hamburgers for 15 cents.","کارل کارچر شنید که رستورانی در همان نزدیکی همبرگرهای ارزان، هرچند درجه‌یک، را به قیمت ۱۵ سنت می‌فروشد."],["You need to improve your grades.","شما باید نمرات خود را ارتقا دهید."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:incline','incline','v','متمایل بودن؛ شیب','/ɪnˈklaɪn/ · to tend toward; a slope','They were inclined to believe that they would be successful in life if they worked hard.','[["They were inclined to believe that they would be successful in life if they worked hard.","آن‌ها تمایل داشتند باور کنند که اگر سخت کار کنند در زندگی موفق خواهند شد."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:output','output','n','خروجی، تولید','/ˈaʊtpʊt/ · the amount produced · ≠ input','Increasing the speed of food preparation increased the kitchen’s output and lowered its costs.','[["Increasing the speed of food preparation increased the kitchen’s output and lowered its costs.","افزایش سرعت آماده‌سازی غذا، بازده آشپزخانه را بالا برد و هزینه‌هایش را پایین آورد."],["Manufacturing output has increased.","بازده تولید افزایش یافته است."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:overlap','overlap','v','همپوشانی داشتن','/ˌoʊvərˈlæp/ · cover, overlie','Although many people worldwide rejected the idea of globalization, business chains were soon overlapping their national borders.','[["Although many people worldwide rejected the idea of globalization, business chains were soon overlapping their national borders.","گرچه بسیاری از مردم در سراسر جهان ایدهٔ جهانی‌شدن را رد می‌کردند، زنجیره‌های تجاری به‌زودی از مرزهای ملی‌شان فراتر رفتند."],["My vacation overlaps with yours.","تعطیلات من با شما همپوشانی دارد."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:reject','reject','v','رد کردن، نپذیرفتن','/rɪˈdʒekt/ · refuse, dismiss','Although many people worldwide rejected the idea of globalization, business chains were soon overlapping their national borders.','[["Although many people worldwide rejected the idea of globalization, business chains were soon overlapping their national borders.","گرچه بسیاری از مردم در سراسر جهان ایدهٔ جهانی‌شدن را رد می‌کردند، زنجیره‌های تجاری به‌زودی از مرزهای ملی‌شان فراتر رفتند."],["It''s obvious why his application was rejected.","واضح است که چرا درخواست او رد شد."]]','ir1',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:appropriate','appropriate','adj','مناسب، شایسته','/əˈprəʊpriət/ · suitable','Schools usually fail to accurately assess the abilities of autistic children because classroom tasks are not appropriate for them.','[["Schools usually fail to accurately assess the abilities of autistic children because classroom tasks are not appropriate for them.","مدارس معمولاً نمی‌توانند توانایی‌های کودکان اوتیسمی را به‌درستی ارزیابی کنند، چون فعالیت‌های کلاس برای آن‌ها مناسب نیست."],["appropriate to the needs of the students","متناسب با نیاز دانش آموزان"]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:assess','assess','v','ارزیابی کردن، سنجیدن','/əˈses/ · evaluate; judge','Schools usually fail to accurately assess the abilities of autistic children because classroom tasks are not appropriate for them.','[["Schools usually fail to accurately assess the abilities of autistic children because classroom tasks are not appropriate for them.","مدارس معمولاً نمی‌توانند توانایی‌های کودکان اوتیسمی را به‌درستی ارزیابی کنند، چون فعالیت‌های کلاس برای آن‌ها مناسب نیست."],["a report to assess the impact of advertising on children","گزارشی برای ارزیابی تاثیر تبلیغات بر کودکان"],["Teachers assess students regularly.","معلمان به طور منظم دانش آموزان را ارزیابی می‌کنند."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:capable','capable','adj','توانا، قادر','/ˈkeɪpəbl/ · able','Most autistic kids can’t pretend because they’re not capable of imagining something that is not real.','[["Most autistic kids can’t pretend because they’re not capable of imagining something that is not real.","بیشتر کودکان اوتیسمی نمی‌توانند وانمود کنند، چون قادر به تصور چیزی که واقعی نیست نیستند."],["She''s a very capable woman/worker/judge.","او یک زن / کارگر / قاضی بسیار توانا است."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:constrain','constrain','v','محدود کردن، مقید کردن','/kənˈstreɪn/ · to limit or restrict','Like most autistic children, Shawn likes repetition, and he can’t constrain his behavior.','[["Like most autistic children, Shawn likes repetition, and he can’t constrain his behavior.","مانند بیشتر کودکان اوتیسمی، شان تکرار را دوست دارد و نمی‌تواند رفتارش را مهار کند."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:infer','infer','v','استنباط کردن، نتیجه گرفتن','/ɪnˈfɜːr/ · deduce, conclude','His mom infers that the noise hurts his ears.','[["His mom infers that the noise hurts his ears.","مادرش نتیجه می‌گیرد که سروصدا گوش‌هایش را آزار می‌دهد."],["From these facts we can infer that crime has been increasing.","از این حقایق می‌توان نتیجه گرفت که جرم و جنایت در حال افزایش است."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:interact','interact','v','تعامل داشتن، برهم‌کنش داشتن','/ˌɪntərˈækt/ · to communicate or act together; to affect each other','Their personalities were thought to be so cold and uncaring that their children grew up unable to speak or interact with others.','[["Their personalities were thought to be so cold and uncaring that their children grew up unable to speak or interact with others.","تصور می‌شد شخصیت آن‌ها چنان سرد و بی‌احساس است که فرزندانشان بدون توانایی صحبت یا تعامل با دیگران بزرگ می‌شوند."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:link','link','n','پیوند، ارتباط','/lɪŋk/ · a connection, relation','For instance, many autistic children are not able to link a printed word with something that is not real.','[["For instance, many autistic children are not able to link a printed word with something that is not real.","برای نمونه، بسیاری از کودکان اوتیسمی نمی‌توانند یک کلمهٔ چاپی را به چیزی که واقعی نیست ربط دهند."],["He retained strong links with the media.","او ارتباط قوی با رسانه‌ها داشت."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:mature','mature','adj','بالغ، پخته','/məˈtʃʊr/ · grown-up, adult','Shawn is very bright, but not academically mature.','[["Shawn is very bright, but not academically mature.","شان بسیار باهوش است، اما از نظر تحصیلی بالغ نیست."],["Laura is very mature for her age.","لورا نسبت به سن خود بسیار بالغ است."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:odd','odd','adj','عجیب، غیرعادی','/ɑːd/ · strange, unusual','The odd hand-flapping behavior is common in kids with autism.','[["The odd hand-flapping behavior is common in kids with autism.","رفتار عجیبِ تکان دادن دست‌ها در کودکان مبتلا به اوتیسم رایج است."],["That drawer is full of odd socks.","آن کشو پر از جوراب‌های عجیب و غریب است."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:participate','participate','v','شرکت کردن، مشارکت کردن','/pɑːrˈtɪsəpeɪt/ · take part','Autistic kids may have excellent physical skills, but they rarely participate in team sports because they don’t understand the rules.','[["Autistic kids may have excellent physical skills, but they rarely participate in team sports because they don’t understand the rules.","کودکان اوتیسمی ممکن است مهارت‌های جسمی عالی داشته باشند، اما به‌ندرت در ورزش‌های تیمی شرکت می‌کنند، چون قوانین را نمی‌فهمند."],["We want more participation in the decision-making.","ما خواهان مشارکت بیشتر در تصمیم گیری هستیم."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:phase','phase','n','مرحله، فاز','/feɪz/ · stage','Shawn’s parents have learned that spinning is not a typical phase of childhood.','[["Shawn’s parents have learned that spinning is not a typical phase of childhood.","والدین شان فهمیده‌اند که چرخیدن دور خود، مرحلهٔ معمولی کودکی نیست."],["The project will be done in three phases.","این پروژه در سه فاز انجام خواهد شد."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:predominant','predominant','adj','غالب، مسلط، عمده','most common or most important','That’s because kids with autism are predominantly male, with boys outnumbering girls by a ratio of 4 to 1.','[["That’s because kids with autism are predominantly male, with boys outnumbering girls by a ratio of 4 to 1.","دلیلش این است که کودکان مبتلا به اوتیسم عمدتاً پسرند و نسبت پسران به دختران ۴ به ۱ است."],["Green is the predominant color in the forest.","سبز رنگ غالب در جنگل است."],["Farming is the predominant industry.","کشاورزی صنعت غالب است."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:ratio','ratio','n','نسبت','/ˈreɪʃiəʊ/ · rate, proportion','That’s because kids with autism are predominantly male, with boys outnumbering girls by a ratio of 4 to 1.','[["That’s because kids with autism are predominantly male, with boys outnumbering girls by a ratio of 4 to 1.","دلیلش این است که کودکان مبتلا به اوتیسم عمدتاً پسرند و نسبت پسران به دختران ۴ به ۱ است."],["Women outnumbered men by a ratio of 3 to 2.","تعداد زنان به نسبت 3 به 2 از مردان بیشتر بود."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:relax','relax','v','آرام شدن، استراحت کردن','/rɪˈlæks/ · be without anxiety','Finally, his handsome face and sturdy body relax.','[["Finally, his handsome face and sturdy body relax.","سرانجام، چهرهٔ زیبا و بدن تنومندش آرام می‌گیرد."],["Just relax and enjoy the movie.","فقط استراحت کنید و از فیلم لذت ببرید."]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:task','task','n','وظیفه، تکلیف','/tæsk/ · duty','Schools usually fail to accurately assess the abilities of autistic children because classroom tasks are not appropriate for them.','[["Schools usually fail to accurately assess the abilities of autistic children because classroom tasks are not appropriate for them.","مدارس معمولاً نمی‌توانند توانایی‌های کودکان اوتیسمی را به‌درستی ارزیابی کنند، چون فعالیت‌های کلاس برای آن‌ها مناسب نیست."],["perform/ complete a task","انجام / تکمیل یک کار"]]','ir1',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:aggregate','aggregate','v','مجموع، کل؛ جمع کردن','/ˈæɡrɪɡət/ · v., n. · collect, amount','As the run-off increases, the aggregation of algae and bacteria increases, further eroding the marine environment.','[["As the run-off increases, the aggregation of algae and bacteria increases, further eroding the marine environment.","با افزایش رواناب، تجمع جلبک‌ها و باکتری‌ها بیشتر می‌شود و محیط دریایی را بیش از پیش فرسوده می‌کند."],["They purchased an aggregate of 3000 shares in the company.","آنها مجموعاً 3000 سهام شرکت را خریداری کردند."]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:annual','annual','adj','سالانه','/ˈænjuəl/ · yearly, once a year','In the United States, an estimated 15,000 tons of automobile oil annually washes off roads into rivers and streams and ultimately into the sea.','[["In the United States, an estimated 15,000 tons of automobile oil annually washes off roads into rivers and streams and ultimately into the sea.","در ایالات متحده، سالانه حدود ۱۵٬۰۰۰ تن روغن خودرو از جاده‌ها به رودخانه‌ها و نهرها و در نهایت به دریا شسته می‌شود."],["The school trip has become an annual event.","سفر مدرسه به یک رویداد سالانه تبدیل شده است."],["The annual rainfall here is low.","میزان بارندگی سالانه در اینجا کم است."]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:compatible','compatible','adj','سازگار، هماهنگ','/kəmˈpætəbl/ · able to exist or work together without problems','Are healthy oceans compatible with an industrialized world?','[["Are healthy oceans compatible with an industrialized world?","آیا اقیانوس‌های سالم با جهانِ صنعتی‌شده سازگارند؟"]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:conduct','conduct','v','اجرا کردن، انجام دادن؛ رفتار','/kənˈdʌkt/ · v., n. · manage, behavior','Such conduct pollutes the water and kills sea life.','[["Such conduct pollutes the water and kills sea life.","چنین رفتاری آب را آلوده می‌کند و جانداران دریایی را می‌کشد."],["We are conducting a survey of consumer attitudes towards organic food.","ما در حال انجام یک نظرسنجی از نگرش مصرف کنندگان نسبت به مواد غذایی ارگانیک هستیم."]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:contribute','contribute','v','کمک کردن، سهم داشتن','/kənˈtrɪbjuːt/ · participate, support','Spills from a single oil tanker can contribute 200,000 tons of oil to the already polluted oceans.','[["Spills from a single oil tanker can contribute 200,000 tons of oil to the already polluted oceans.","نشت نفت از تنها یک نفتکش می‌تواند ۲۰۰٬۰۰۰ تن نفت به اقیانوس‌های از پیش آلوده بیفزاید."],["The agency is mainly financed from voluntary contributions.","این آژانس عمدتاً از کمک‌های داوطلبانه تأمین می‌شود."],["Everyone contributed to the project.","همه در این پروژه مشارکت داشتند."]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:erode','erode','v','فرسایش یافتن، فرسودن','/ɪˈrəʊd/ · wear away, rot','As the run-off increases, the aggregation of algae and bacteria increases, further eroding the marine environment.','[["As the run-off increases, the aggregation of algae and bacteria increases, further eroding the marine environment.","با افزایش رواناب، تجمع جلبک‌ها و باکتری‌ها بیشتر می‌شود و محیط دریایی را بیش از پیش فرسوده می‌کند."],["the gradual erosion of our civil liberties","فرسایش تدریجی آزادی‌های مدنی ما"],["Waves eroded the cliffs.","امواج صخره‌ها را فرسایش دادند."]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:finite','finite','adj','محدود، متناهی','/ˈfaɪnaɪt/ · limited','For all of human history, people regarded the oceans as an indestructible and infinite resource.','[["For all of human history, people regarded the oceans as an indestructible and infinite resource.","در سراسر تاریخ بشر، مردم اقیانوس‌ها را منبعی نابودنشدنی و بی‌پایان می‌دانستند."],["the earth''s finite supply of natural resources","عرضه متناهی زمین از منابع طبیعی"]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:impact','impact','n','تأثیر، اثر','/ˈɪmpækt/ · influence','Until recently, humans had little impact on the oceans.','[["Until recently, humans had little impact on the oceans.","تا همین اواخر، انسان‌ها تأثیر کمی بر اقیانوس‌ها داشتند."],["We need to assess the impact on climate change.","ما باید تاثیر آن بر تغییرات آب و هوایی را ارزیابی کنیم."],["Tourism has a big impact on the economy.","گردشگری تاثیر زیادی بر اقتصاد دارد."]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:occupy','occupy','v','اشغال کردن، ساکن بودن در','/ˈɑːkjupaɪ/ · reside, inhabit','The oceans of the world occupy over 70% of the earth’s surface.','[["The oceans of the world occupy over 70% of the earth’s surface.","اقیانوس‌های جهان بیش از ۷۰٪ سطح زمین را فرا گرفته‌اند."],["They occupied the house for 35 years.","آنها 35 سال خانه را اشغال کردند."]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:process','process','n','فرایند، روند','/ˈprəʊses/ · a series of actions or steps','In the process, they almost destroyed the species.','[["In the process, they almost destroyed the species.","در این روند، آن‌ها تقریباً این گونه را نابود کردند."],["the aging process","روند پیری"],["Photosynthesis is a complex process.","فتوسنتز یک فرآیند پیچیده است."]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:temporary','temporary','adj','موقت','/ˈtempəreri/ · not permanent','Governments can also create sea reserves, areas where fishing is temporarily banned until the fish population increases.','[["Governments can also create sea reserves, areas where fishing is temporarily banned until the fish population increases.","دولت‌ها همچنین می‌توانند ذخیره‌گاه‌های دریایی ایجاد کنند؛ مناطقی که ماهیگیری در آن‌ها موقتاً ممنوع است تا جمعیت ماهی‌ها افزایش یابد."],["The ceasefire will only provide a temporary solution to the crisis.","آتش بس تنها راه حلی موقت برای بحران ارائه می‌کند."]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:terminate','terminate','v','خاتمه دادن، پایان دادن','/ˈtɜːrmɪneɪt/ · end, complete','What can be done to terminate the steady destruction of the oceans?','[["What can be done to terminate the steady destruction of the oceans?","چه کاری می‌توان کرد تا تخریب پیوستهٔ اقیانوس‌ها پایان یابد؟"],["You may face a reduction or terminate of benefits.","ممکن است با کاهش یا خاتمه مزایا مواجه شوید."]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:trace','trace','v','ردیابی کردن، پیدا کردن','/treɪs/ · find, detect','However, scientists are planning to trace the development of vents by revisiting some they studied earlier.','[["However, scientists are planning to trace the development of vents by revisiting some they studied earlier.","با این حال، دانشمندان قصد دارند با بازدید دوباره از برخی دریچه‌هایی که پیش‌تر بررسی کرده‌اند، روند شکل‌گیری آن‌ها را دنبال کنند."],["We finally traced him to an address in Mashhad!","بالاخره ردش را به آدرسی در مشهد رساندیم!"]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:ultimate','ultimate','adj','نهایی، غایی؛ بزرگ‌ترین','final; the greatest or most extreme','However, as the earth’s population increases, human activity will ultimately destroy the oceans unless immediate steps are taken.','[["However, as the earth’s population increases, human activity will ultimately destroy the oceans unless immediate steps are taken.","اما با افزایش جمعیت زمین، فعالیت انسان سرانجام اقیانوس‌ها را نابود خواهد کرد، مگر اینکه فوراً اقداماتی انجام شود."],["Our ultimate goal is to protect the forest.","هدف نهایی ما حفاظت از جنگل است."],["The ultimate responsibility lies with the government.","مسئولیت نهایی بر عهده دولت است."]]','ir1',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:advocate','advocate','n','طرفدار، مدافع؛ حمایت کردن','/ˈædvəkeɪt/ · n., v. · support, back','When the process of making rubber was perfected in 1851, dentists immediately advocated its use as a base material for dentures.','[["When the process of making rubber was perfected in 1851, dentists immediately advocated its use as a base material for dentures.","وقتی فرایند ساخت لاستیک در سال ۱۸۵۱ کامل شد، دندان‌پزشکان بی‌درنگ از استفادهٔ آن به‌عنوان مادهٔ پایهٔ دندان مصنوعی حمایت کردند."],["He was an untiring advocate of economic reform.","او مدافع خستگی ناپذیر اصلاحات اقتصادی بود."],["She advocates for animal rights.","او مدافع حقوق حیوانات است."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:alternative','alternative','adj','جایگزین، گزینه','/ɒːlˈtɜːrnətɪv/ · adj., n. · option, choice','There is now a surgical alternative to improve hearing without an external device.','[["There is now a surgical alternative to improve hearing without an external device.","اکنون یک جایگزین جراحی برای بهبود شنوایی بدون دستگاه بیرونی وجود دارد."],["Have you any alternative suggestions?","آیا پیشنهاد جایگزینی دارید؟"],["Cycling is a healthy alternative to driving.","دوچرخه سواری جایگزین سالمی برای رانندگی است."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:confine','confine','v','محدود کردن، محصور کردن','/kənˈfaɪn/ · restrict','The exploration of an ancient Mayan burial site in Honduras uncovered the tomb of a young woman, confined there for 1,400 years.','[["The exploration of an ancient Mayan burial site in Honduras uncovered the tomb of a young woman, confined there for 1,400 years.","کاوش در یک گورگاه باستانی مایاها در هندوراس، آرامگاه زن جوانی را آشکار کرد که ۱۴۰۰ سال در آن‌جا محبوس بود."],["It wasn''t easy to sleep in such a confined space.","خوابیدن در چنین فضای محدودی آسان نبود."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:discriminate','discriminate','v','تبعیض قائل شدن؛ تمایز قائل شدن','/dɪˈskrɪmɪneɪt/ · to treat unfairly; to see a difference between','They provide not only better amplification, but also better discrimination between various sounds.','[["They provide not only better amplification, but also better discrimination between various sounds.","آن‌ها نه‌تنها تقویت صدای بهتری فراهم می‌کنند، بلکه تمایز بهتری میان صداهای مختلف هم ایجاد می‌کنند."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:error','error','n','خطا، اشتباه','/ˈerər/ · mistake','Somehow, he made an error and contacted with a live wire on the ground that gave him a 7,200-volt shock of electricity.','[["Somehow, he made an error and contacted with a live wire on the ground that gave him a 7,200-volt shock of electricity.","به نحوی اشتباهی کرد و با سیم برق‌داری روی زمین تماس پیدا کرد که شوک الکتریکی ۷۲۰۰ ولتی به او وارد کرد."],["I made an error in my calculations.","من در محاسباتم اشتباه کردم."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:evaluate','evaluate','v','ارزیابی کردن','/ɪˈvæljueɪt/ · assess','A medical evaluation can determine whether this alternative—a cochlear implant—might be right for someone with a hearing loss.','[["A medical evaluation can determine whether this alternative—a cochlear implant—might be right for someone with a hearing loss.","یک ارزیابی پزشکی می‌تواند مشخص کند که آیا این جایگزین — کاشت حلزون — برای فرد دچار کم‌شنوایی مناسب است یا نه."],["We need to evaluate our options.","ما باید گزینه‌های خود را ارزیابی کنیم."],["We need to evaluate the results.","ما باید نتایج را ارزیابی کنیم."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:impose','impose','v','تحمیل کردن، وضع کردن','/ɪmˈpəʊz/ · force','Was the dental implant a punishment imposed on her, or was it a voluntary procedure?','[["Was the dental implant a punishment imposed on her, or was it a voluntary procedure?","آیا ایمپلنت دندان مجازاتی بود که بر او تحمیل شد، یا عملی داوطلبانه بود؟"],["The government imposed a ban on the sale of ivory.","دولت ممنوعیت فروش عاج را وضع کرد."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:incentive','incentive','n','انگیزه، مشوق','/ɪnˈsentɪv/ · motivation','Over time, the incentive to survive led people to develop devices that would fix these impaired conditions.','[["Over time, the incentive to survive led people to develop devices that would fix these impaired conditions.","به مرور زمان، انگیزهٔ بقا مردم را به ساختن ابزارهایی واداشت که این ناتوانی‌ها را برطرف کند."],["There is no incentive for people to save fuel.","هیچ انگیزه ای برای مردم برای صرفه جویی در مصرف سوخت وجود ندارد."],["Tax incentives encourage green energy.","مشوق‌های مالیاتی انرژی سبز را تشویق می‌کند."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:objective','objective','n','هدف؛ عینی، بی‌طرف','/əbˈdʒektɪv/ · goal, unbiased','The objective of the earliest lenses was to help people see things that were close up so they could do tasks like carving or sewing.','[["The objective of the earliest lenses was to help people see things that were close up so they could do tasks like carving or sewing.","هدف نخستین عدسی‌ها این بود که به مردم کمک کنند چیزهای نزدیک را ببینند تا بتوانند کارهایی مانند کنده‌کاری یا خیاطی انجام دهند."],["to achieve/meet/accomplish your objectives","برای دستیابی به / برآورده کردن / دستیابی به اهداف خود"]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:proportion','proportion','n','نسبت، بخش','/prəˈpɔːʃən/ · ratio','Today a disproportionate amount of research into brain-controlled artificial arms is focused on implanting sensors in the brain to link the brain to the arm.','[["Today a disproportionate amount of research into brain-controlled artificial arms is focused on implanting sensors in the brain to link the brain to the arm.","امروزه حجم نامتناسبی از پژوهش‌ها دربارهٔ دست‌های مصنوعیِ کنترل‌شونده با مغز، بر کاشت حسگر در مغز برای اتصال مغز به دست متمرکز است."],["The decision affects a significant proportion of the population.","این تصمیم بر بخش قابل توجهی از جمعیت تأثیر می‌گذارد."],["A large proportion of students live at home.","بخش زیادی از دانش آموزان در خانه زندگی می‌کنند."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:sum','sum','n','مبلغ، مقدار؛ مجموع','/sʌm/ · amount','More recently, a real bionic man has been created, and for a sum nearly as great as the original one.','[["More recently, a real bionic man has been created, and for a sum nearly as great as the original one.","به‌تازگی یک انسان بیونیک واقعی ساخته شده است، آن هم با هزینه‌ای تقریباً به بزرگی نمونهٔ اصلی."],["We donated a small sum (of money) to the charity.","مبلغ ناچیزی (پول) به خیریه اهدا کردیم."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:suspend','suspend','v','معلق کردن، به تعویق انداختن','/səˈspend/ · temporarily inactive','Modern framed glasses, suspended from the ears by earpieces, were uncommon until the 19th century.','[["Modern framed glasses, suspended from the ears by earpieces, were uncommon until the 19th century.","عینک‌های قاب‌دار امروزی که با دسته‌ها از گوش آویزان‌اند، تا قرن نوزدهم رایج نبودند."],["The judge suspended judgment until January 15.","قاضی قضاوت را تا 15 ژانویه به حالت تعلیق درآورد."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:tense','tense','adj','پرتنش، نگران','/tens/ · nervous and anxious; stretched tight','Early glasses were held in the hand or clipped on the nose, held there by the tension of the stiff wire they were made from.','[["Early glasses were held in the hand or clipped on the nose, held there by the tension of the stiff wire they were made from.","عینک‌های اولیه در دست گرفته می‌شدند یا روی بینی گیره می‌شدند و با کشش سیم سفتی که از آن ساخته شده بودند در جای خود می‌ماندند."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir1:voluntary','voluntary','adj','داوطلبانه','/ˈvɑːlənteri/ · of your own free will','Was the dental implant a punishment imposed on her, or was it a voluntary procedure?','[["Was the dental implant a punishment imposed on her, or was it a voluntary procedure?","آیا ایمپلنت دندان مجازاتی بود که بر او تحمیل شد، یا عملی داوطلبانه بود؟"],["She made a voluntary decision to go back to school.","او داوطلبانه تصمیم گرفت که به مدرسه برگردد."]]','ir1',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:assume','assume','v','فرض کردن، پنداشتن','/əˈsuːm/ · presume','The homes are essentially artificial caves, but don’t assume there is anything primitive about them.','[["The homes are essentially artificial caves, but don’t assume there is anything primitive about them.","این خانه‌ها در اصل غارهایی مصنوعی‌اند، اما گمان نکنید چیز ابتدایی‌ای در آن‌ها هست."],["I think we can safely assume that he is out of town.","فکر می‌کنم با خیال راحت می‌توانیم فرض کنیم که او خارج از شهر است."],["I assume you have heard the news.","فکر می‌کنم شما این خبر را شنیده اید."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:create','create','v','ایجاد کردن، خلق کردن، ساختن','/kriˈeɪt/ · make, produce','To create a typical dug-out, you need a hill and a drill.','[["To create a typical dug-out, you need a hill and a drill.","برای ساختن یک خانهٔ کنده‌شدهٔ معمولی، به یک تپه و یک دستگاه حفاری نیاز دارید."],["He believes the universe was created by a big explosion.","او معتقد است که جهان بر اثر یک انفجار بزرگ ایجاد شده است."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:emerge','emerge','v','پدیدار شدن، ظاهر شدن','/ɪˈmɜːrdʒ/ · appear','If the hill doesn’t have a side of exposed rock, bulldozers push sand and loose soil away until a sandstone face emerges.','[["If the hill doesn’t have a side of exposed rock, bulldozers push sand and loose soil away until a sandstone face emerges.","اگر دامنهٔ تپه سنگ نمایان نداشته باشد، بولدوزرها شن و خاک سست را کنار می‌زنند تا سطحی از ماسه‌سنگ پدیدار شود."],["The facts emerged after a lengthy investigation.","حقایق پس از یک تحقیق طولانی آشکار شد."],["New species emerged after the ice age.","گونه‌های جدیدی پس از عصر یخبندان پدیدار شدند."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:environment','environment','n','محیط، محیط زیست','/ɪnˈvaɪrənmənt/ · surroundings; the natural world','In hopes of getting rich, gemstone miners endure the harsh outback environment.','[["In hopes of getting rich, gemstone miners endure the harsh outback environment.","معدنچیان سنگ‌های قیمتی به امید ثروتمند شدن، محیط خشن مناطق دورافتادهٔ استرالیا را تحمل می‌کنند."],["We''re trying to create a better business environment.","ما در تلاش هستیم تا فضای کسب و کار بهتری ایجاد کنیم."],["We must protect the environment.","ما باید از محیط زیست محافظت کنیم."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:ethnic','ethnic','adj','قومی، نژادی','/ˈeθnɪk/ · racial, tribal','The current population of 3,500 includes members of more than 40 ethnic or national groups, including Greeks, Poles, Germans, Italians, Serbs, and Croats.','[["The current population of 3,500 includes members of more than 40 ethnic or national groups, including Greeks, Poles, Germans, Italians, Serbs, and Croats.","جمعیت کنونی ۳۵۰۰ نفری شامل اعضای بیش از ۴۰ گروه قومی یا ملی، از جمله یونانی‌ها، لهستانی‌ها، آلمانی‌ها، ایتالیایی‌ها، صرب‌ها و کروات‌ها است."],["The school teaches pupils from different ethnic groups.","این مدرسه به دانش آموزانی از اقوام مختلف آموزش می‌دهد."],["The city has many ethnic groups.","این شهر دارای اقوام بسیاری است."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:immigrate','immigrate','v','مهاجرت کردن (به کشوری)','','Most miners arrived in the 1960s and 1970s, immigrating to Australia and Coober Pedy from around the globe.','[["Most miners arrived in the 1960s and 1970s, immigrating to Australia and Coober Pedy from around the globe.","بیشتر معدنچیان در دهه‌های ۱۹۶۰ و ۱۹۷۰ از سراسر جهان به استرالیا و کوبر پدی مهاجرت کردند."],["His parents immigrated to Canada in 1990.","والدین او در سال 1990 به کانادا مهاجرت کردند."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:liberal','liberal','adj','آزادی‌خواه، لیبرال','/ˈlɪbərəl/ · with a lot of political & economic freedom','The miners may enjoy a rough kind of fun—including occasional fights—but the community takes a liberal attitude toward this behavior.','[["The miners may enjoy a rough kind of fun—including occasional fights—but the community takes a liberal attitude toward this behavior.","معدنچیان شاید از نوعی تفریح خشن — از جمله دعواهای گاه‌به‌گاه — لذت ببرند، اما جامعه نگرشی آزادمنشانه نسبت به این رفتار دارد."],["liberal attitudes/views/ policies","نگرش‌ها / دیدگاه‌ها / سیاست‌های لیبرال"]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:locate','locate','v','پیدا کردن (مکان)؛ قرار دادن','/ləʊˈkeɪt/ · to find the exact position of; to put in a place','Just outside town are colorful rocky areas, used as the location for numerous films, including Red Planet and Mad Max Beyond Thunderdome.','[["Just outside town are colorful rocky areas, used as the location for numerous films, including Red Planet and Mad Max Beyond Thunderdome.","درست بیرون شهر مناطق سنگی رنگارنگی هست که محل فیلم‌برداری فیلم‌های زیادی، از جمله «سیارهٔ سرخ» و «مکس دیوانه: فراسوی گنبد تندر» بوده است."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:notwithstanding','notwithstanding','prep','با وجود، علی‌رغم','/ˌnɑːtwɪθˈstændɪŋ/ · in spite of','Its rough edges notwithstanding, Coober Pedy has a warmth and raw charm.','[["Its rough edges notwithstanding, Coober Pedy has a warmth and raw charm.","کوبر پدی با وجود ناهمواری‌هایش، گرما و جذابیتی بکر دارد."],["Notwithstanding his parents objections; he left of the house.","با وجود مخالفت والدینش؛ او از خانه خارج شد"],["Notwithstanding the costs, the project continued.","با وجود هزینه‌ها، پروژه ادامه یافت."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:predict','predict','v','پیش‌بینی کردن','/prɪˈdɪkt/ · foretell, forecast','Some town planners predict that Coober Pedy will sprawl out to great distances as more miners seek a place to dig.','[["Some town planners predict that Coober Pedy will sprawl out to great distances as more miners seek a place to dig.","برخی برنامه‌ریزان شهری پیش‌بینی می‌کنند که با جست‌وجوی معدنچیان بیشتر برای جایی جهت حفاری، کوبر پدی تا فاصله‌های زیادی گسترش خواهد یافت."],["Newspapers predicted that Davis would be re- elected.","روزنامه‌ها پیش بینی کردند که دیویس دوباره انتخاب خواهد شد."],["Experts predict more rain.","کارشناسان بارندگی بیشتری را پیش بینی می‌کنند."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:similar','similar','adj','مشابه، همانند','/ˈsɪmələr/ · almost the same','Three-bedroom plans are common, and having your cave drilled out costs about the same as building a new above-ground home of similar size.','[["Three-bedroom plans are common, and having your cave drilled out costs about the same as building a new above-ground home of similar size.","طرح‌های سه‌خوابه رایج‌اند و حفر غارتان تقریباً به اندازهٔ ساختن یک خانهٔ نوی هم‌اندازه روی زمین هزینه دارد."],["We have similar tastes in music.","ما در موسیقی سلیقه‌های مشابهی داریم."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:structure','structure','n','ساختار، ساختمان','/ˈstrʌktʃər/ · n., v. · building or form','Needless to say, the structure is solid, which creates some challenges.','[["Needless to say, the structure is solid, which creates some challenges.","ناگفته پیداست که این سازه محکم است، و همین چالش‌هایی ایجاد می‌کند."],["the structure of an atom","ساختار یک اتم"],["The structure of DNA is a double helix.","ساختار DNA یک مارپیچ دوگانه است."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:technique','technique','n','فن، تکنیک، روش','/tekˈniːk/ · method','Drilling, with huge machines meant to dig tunnels through mountains, is now the technique of choice.','[["Drilling, with huge machines meant to dig tunnels through mountains, is now the technique of choice.","حفاری با ماشین‌های عظیمی که برای کندن تونل در کوه‌ها ساخته شده‌اند، اکنون روش برگزیده است."],["We learned some techniques for relieving stress.","چند تکنیک برای رهایی از استرس یاد گرفتیم."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:unique','unique','adj','منحصربه‌فرد، بی‌نظیر','/juˈniːk/ · be the only one of its kind','Some fell in love with the unique (though sometimes scary) scenery.','[["Some fell in love with the unique (though sometimes scary) scenery.","برخی دلباختهٔ مناظر بی‌همتا (هرچند گاهی ترسناک) آن‌جا شدند."],["Each person''s DNA is unique.","DNA هر فرد منحصر به فرد است."],["Every person''s fingerprints are unique.","اثر انگشت هر فردی منحصر به فرد است."]]','ir2',1,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:consume','consume','v','مصرف کردن','/kənˈsuːm/ · use','To turn things around, you have to convert your product’s old-fashioned image into something new, and make sure consumers get the message.','[["To turn things around, you have to convert your product’s old-fashioned image into something new, and make sure consumers get the message.","برای تغییر اوضاع، باید تصویر قدیمی محصولتان را به چیزی تازه تبدیل کنید و مطمئن شوید مصرف‌کنندگان پیام را دریافت می‌کنند."],["Many consumers are not comfortable making purchases on the Internet.","بسیاری از مصرف کنندگان برای خرید از طریق اینترنت راحت نیستند."],["Cows consume a lot of grass.","گاوها علف زیادی مصرف می‌کنند."]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:contradict','contradict','v','تناقض داشتن','to be opposite to','When that happens to a brand with a worldwide presence, the company may get contradictory results.','[["When that happens to a brand with a worldwide presence, the company may get contradictory results.","وقتی این اتفاق برای برندی با حضور جهانی رخ دهد، شرکت ممکن است نتایج متناقضی بگیرد."],["The new data contradict the earlier findings.","داده‌های جدید با یافته‌های قبلی در تضاد است."],["The evidence contradicts his story.","شواهد با داستان او در تناقض است."]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:convert','convert','v','تبدیل کردن','/kənˈvɜːrt/ · change','To turn things around, you have to convert your product’s old-fashioned image into something new, and make sure consumers get the message.','[["To turn things around, you have to convert your product’s old-fashioned image into something new, and make sure consumers get the message.","برای تغییر اوضاع، باید تصویر قدیمی محصولتان را به چیزی تازه تبدیل کنید و مطمئن شوید مصرف‌کنندگان پیام را دریافت می‌کنند."],["The sofa converts to a bed.","مبل به تخت تبدیل می‌شود."]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:corporate','corporate','adj','شرکتی','≈ organizational, business-related — Cambridge 15 · Test 1 · Passage 2: Corporate Social Responsibility (CSR)','The McDonald’s restaurant franchise offers just one prominent case of a corporation fighting to guide its brand through these difficult situations.','[["The McDonald’s restaurant franchise offers just one prominent case of a corporation fighting to guide its brand through these difficult situations.","امتیاز رستوران‌های مک‌دونالد تنها یک نمونهٔ برجسته از شرکتی است که برای هدایت برندش در این شرایط دشوار تلاش می‌کند."],["Corporate policies must align with ethical principles.","سیاست‌های شرکت باید با اصول اخلاقی همسو باشد."]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:equate','equate','v','برابر دانستن، یکی دانستن','/iˈkweɪt/ · to consider one thing to be the same as another','They must equate your product with some larger idea that has nothing to do with shoes—beauty, wealth, or even world peace.','[["They must equate your product with some larger idea that has nothing to do with shoes—beauty, wealth, or even world peace.","آن‌ها باید محصول شما را با ایده‌ای بزرگ‌تر که ربطی به کفش ندارد — زیبایی، ثروت یا حتی صلح جهانی — یکی بدانند."]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:finance','finance','n','امور مالی؛ تأمین مالی کردن','/ˈfaɪnæns/ · the management of money; to provide money for','It can finance many of its operations by, for instance, allowing its name to appear on products and selling advertising space alongside its racetracks.','[["It can finance many of its operations by, for instance, allowing its name to appear on products and selling advertising space alongside its racetracks.","این شرکت می‌تواند بسیاری از فعالیت‌هایش را تأمین مالی کند؛ برای نمونه با اجازه دادن به درج نامش روی محصولات و فروش فضای تبلیغاتی در کنار پیست‌هایش."]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:label','label','n','برچسب','/ˈleɪbl/ · tag','The brand is a kind of label, a device for creating recognition.','[["The brand is a kind of label, a device for creating recognition.","برند نوعی برچسب است؛ ابزاری برای ایجاد شناخت."],["The name is prominently displayed on the label.","نام به طور برجسته روی برچسب نمایش داده می‌شود."]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:medium','medium','n','رسانه، وسیله، واسطه','/ˈmiːdiəm/ · means, method','Because NASCAR has a connection to such a large segment of the population, it is a medium in itself.','[["Because NASCAR has a connection to such a large segment of the population, it is a medium in itself.","از آن‌جا که نسکار با بخش بسیار بزرگی از جمعیت ارتباط دارد، خودش یک رسانه است."],["using the latest technology as a medium for job creation","استفاده از آخرین فناوری به عنوان ابزاری برای ایجاد اشتغال"]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:presume','presume','v','فرض کردن، گمان کردن','/prɪˈzuːm/ · assume, suppose','A customer might buy Nike shoes because she considers herself a no-nonsense athlete—and she wants others to presume this, too.','[["A customer might buy Nike shoes because she considers herself a no-nonsense athlete—and she wants others to presume this, too.","ممکن است مشتری کفش نایکی بخرد، چون خود را ورزشکاری جدی می‌داند — و می‌خواهد دیگران هم همین را فرض کنند."],["There is no scientific evidence to support such presumptions.","هیچ مدرک علمی برای حمایت از چنین فرضیاتی وجود ندارد."],["I presume you have read the report.","من فکر می‌کنم شما گزارش را خوانده اید."]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:register','register','v','ثبت‌نام کردن، ثبت کردن','/ˈredʒɪstər/ · enroll','It even registers with people who have never seen one of the company’s cars.','[["It even registers with people who have never seen one of the company’s cars.","حتی در ذهن کسانی که هرگز یکی از خودروهای این شرکت را ندیده‌اند جا می‌افتد."],["How many students have registered for English classes?","چند دانش آموز در کلاس‌های زبان انگلیسی ثبت نام کرده اند؟"]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:revenue','revenue','n','درآمد (دولت یا شرکت)','/ˈrevənuː/ · income','Nevertheless, other companies have sped past you in the race for fame and the revenue that goes with it.','[["Nevertheless, other companies have sped past you in the race for fame and the revenue that goes with it.","با این حال، شرکت‌های دیگر در رقابت برای شهرت و درآمدی که با آن همراه است از شما جلو زده‌اند."],["advertising revenue","درآمد تبلیغاتی"]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:subsidy','subsidy','n','یارانه، کمک مالی دولتی','≈ financial aid, grant — Cambridge 10 · Test 2 · Passage 1: European Transport Systems','For TV networks and movie companies, product placement is great because it costs very little while earning significant income to help subsidize their shows and films.','[["For TV networks and movie companies, product placement is great because it costs very little while earning significant income to help subsidize their shows and films.","برای شبکه‌های تلویزیونی و شرکت‌های فیلم‌سازی، تبلیغ محصول در فیلم عالی است، چون هزینهٔ بسیار کمی دارد و درآمد قابل‌توجهی برای کمک به تأمین هزینهٔ برنامه‌ها و فیلم‌هایشان به همراه دارد."],["Governments offer subsidies for electric buses.","دولت‌ها برای اتوبوس‌های برقی یارانه می‌دهند."]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:symbol','symbol','n','نماد','/ˈsɪmbl/ · an object or picture that represents sth else','Products with the logos of the other companies are status symbols.','[["Products with the logos of the other companies are status symbols.","محصولاتی که لوگوی شرکت‌های دیگر را دارند، نماد منزلت اجتماعی‌اند."],["Wedding rings are symbols of eternal love.","حلقه‌های ازدواج نماد عشق ابدی هستند."]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:theme','theme','n','مضمون، موضوع اصلی','/θiːm/ · main idea','Rolls-Royce turned 100 years old in 2004, and the brand continues to use the themes of integrity, dependability, and even Britishness in its advertising.','[["Rolls-Royce turned 100 years old in 2004, and the brand continues to use the themes of integrity, dependability, and even Britishness in its advertising.","رولزرویس در سال ۲۰۰۴ صدساله شد و این برند همچنان از مضامین درستکاری، قابل‌اعتماد بودن و حتی بریتانیایی بودن در تبلیغاتش استفاده می‌کند."],["The book''s theme is the conflict between love and duty.","موضوع کتاب تضاد عشق و وظیفه است."]]','ir2',2,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:adjacent','adjacent','adj','مجاور، همسایه','/əˈdʒeɪsnt/ · near or close to','The difference in types of systems is illustrated by another camera system in Tampa, this one in Ybor City, an entertainment district adjacent to downtown Tampa.','[["The difference in types of systems is illustrated by another camera system in Tampa, this one in Ybor City, an entertainment district adjacent to downtown Tampa.","تفاوت انواع سیستم‌ها را سیستم دوربین دیگری در تامپا نشان می‌دهد؛ این یکی در ایبور سیتی، محله‌ای تفریحی در مجاورت مرکز شهر تامپا."],["They lived in a house adjacent to the railway.","آنها در خانه ای در مجاورت راه آهن زندگی می‌کردند."],["The lab is adjacent to the library.","آزمایشگاه در مجاورت کتابخانه قرار دارد."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:analyze','analyze','v','تحلیل کردن','to examine in detail','It analyzes facial characteristics (the features of the face) to establish a person’s identity.','[["It analyzes facial characteristics (the features of the face) to establish a person’s identity.","این سیستم ویژگی‌های چهره را تحلیل می‌کند تا هویت فرد را مشخص کند."],["Scientists analyzed the data.","دانشمندان داده‌ها را تجزیه و تحلیل کردند."],["Scientists analyzed the water samples.","دانشمندان نمونه‌های آب را تجزیه و تحلیل کردند."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:anticipate','anticipate','v','پیش‌بینی کردن، انتظار داشتن','/ænˈtɪsɪpeɪt/ · expect, predict','The organizers of any huge sporting event have to anticipate trouble and try to stop it before it starts.','[["The organizers of any huge sporting event have to anticipate trouble and try to stop it before it starts.","برگزارکنندگان هر رویداد ورزشی بزرگ باید دردسرها را پیش‌بینی کنند و پیش از شروع، جلوی آن‌ها را بگیرند."],["Are you anticipating a lot of people at the party tonight?","آیا منتظر حضور افراد زیادی در مهمانی امشب هستید؟"],["We anticipate a busy summer.","تابستان شلوغی را پیش بینی می‌کنیم."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:consequent','consequent','adj','ناشی از، حاصل','/ˈkɒnsɪkwənt/ · happening as a result of something','The police might see a crime as it was happening or use the video to help in any consequent investigations.','[["The police might see a crime as it was happening or use the video to help in any consequent investigations.","پلیس ممکن بود جرمی را در حین وقوع ببیند یا از ویدئو برای کمک به تحقیقات بعدی استفاده کند."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:controversy','controversy','n','جدل، مناقشه','/ˈkɑːntrəvɜːrsi/ · dispute, debate','In the United States, it has stirred some controversy about possible threats to the privacy rights of individuals.','[["In the United States, it has stirred some controversy about possible threats to the privacy rights of individuals.","در ایالات متحده، این موضوع جنجال‌هایی دربارهٔ تهدیدهای احتمالی علیه حق حریم خصوصی افراد برانگیخته است."],["The judges'' decision provoked controversy.","تصمیم داوران جنجال برانگیخت."],["The decision caused controversy.","این تصمیم جنجال به پا کرد."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:data','data','n','داده‌ها، اطلاعات','/ˈdeɪtə, ˈdɑːtə/ · information or facts','Each face seen by the gate-mounted cameras was compared to the data in local and federal law-enforcement computer systems.','[["Each face seen by the gate-mounted cameras was compared to the data in local and federal law-enforcement computer systems.","هر چهره‌ای که دوربین‌های نصب‌شده روی ورودی‌ها می‌دیدند، با داده‌های سیستم‌های رایانه‌ای پلیس محلی و فدرال مقایسه می‌شد."],["The analysis was based on data collected in the field.","تجزیه و تحلیل بر اساس داده‌های جمع آوری شده در میدان انجام شد."],["The data show a clear pattern.","داده‌ها یک الگوی واضح را نشان می‌دهد."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:device','device','n','دستگاه، وسیله','/dɪˈvaɪs/ · tool','They argue that machines are easily fooled by such simple devices as hats, new hairstyles, or glasses.','[["They argue that machines are easily fooled by such simple devices as hats, new hairstyles, or glasses.","آن‌ها استدلال می‌کنند که ماشین‌ها به‌آسانی با ابزارهای ساده‌ای مانند کلاه، مدل موی جدید یا عینک فریب می‌خورند."],["a device for separating metal from garbage.","وسیله ای برای جدا کردن فلز از زباله"]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:equip','equip','v','مجهز کردن','/ɪˈkwɪp/ · to provide with the tools or things needed','Banks, shopping malls, and government buildings are already equipped with security cameras, and no one has a problem with that.','[["Banks, shopping malls, and government buildings are already equipped with security cameras, and no one has a problem with that.","بانک‌ها، مراکز خرید و ساختمان‌های دولتی از قبل به دوربین‌های امنیتی مجهزند و هیچ‌کس با آن مشکلی ندارد."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:federal','federal','adj','فدرال، مربوط به دولت مرکزی','/ˈfedərəl/ · relating to the central government of a country','Each face seen by the gate-mounted cameras was compared to the data in local and federal law-enforcement computer systems.','[["Each face seen by the gate-mounted cameras was compared to the data in local and federal law-enforcement computer systems.","هر چهره‌ای که دوربین‌های نصب‌شده روی ورودی‌ها می‌دیدند، با داده‌های سیستم‌های رایانه‌ای پلیس محلی و فدرال مقایسه می‌شد."],["The US has local, state, and federal courts.","ایالات متحده دارای دادگاه‌های محلی، ایالتی و فدرال است."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:involve','involve','v','شامل شدن، در بر داشتن؛ درگیر کردن','/ɪnˈvɒlv/ · include','One big difference is that a system like the one used at the Super Bowl involves “biometric” technology.','[["One big difference is that a system like the one used at the Super Bowl involves “biometric” technology.","یک تفاوت بزرگ این است که سیستمی مانند آنچه در سوپربول استفاده شد، فناوری «بیومتریک» را به کار می‌گیرد."],["More than 30 software firms were involved in the project.","بیش از 30 شرکت نرم افزاری در این پروژه مشارکت داشتند."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:justify','justify','v','توجیه کردن','/ˈdʒʌstɪfaɪ/ · explain, rationalize','Security officials say the face-recognition (FR) system’s great benefits justify any small inconvenience.','[["Security officials say the face-recognition (FR) system’s great benefits justify any small inconvenience.","مقامات امنیتی می‌گویند مزایای بزرگ سیستم تشخیص چهره هر ناراحتی کوچکی را توجیه می‌کند."],["He tried to present a justification for his behavior.","سعی کرد توجیهی برای رفتارش ارائه کند."],["Can the high cost be justified?","آیا هزینه بالا قابل توجیه است؟"]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:legal','legal','adj','قانونی، حقوقی','/ˈliːɡəl/ · allowed by law','The ID-making equipment can be legally purchased because it has other, perfectly legal uses.','[["The ID-making equipment can be legally purchased because it has other, perfectly legal uses.","تجهیزات ساخت کارت شناسایی را می‌توان قانونی خرید، چون کاربردهای کاملاً قانونی دیگری هم دارد."],["What the company has done is perfectly legal.","کاری که این شرکت انجام داده کاملا قانونی است."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:modify','modify','v','اصلاح کردن، تغییر دادن','/ˈmɑːdɪfaɪ/ · change','Then Tampa modified those cameras to link directly to the police department’s own database.','[["Then Tampa modified those cameras to link directly to the police department’s own database.","سپس تامپا آن دوربین‌ها را طوری تغییر داد که مستقیماً به پایگاه دادهٔ ادارهٔ پلیس وصل شوند."],["The regulations can only be modified by a special committee.","این مقررات فقط توسط یک کمیته ویژه قابل تغییر است."],["The plan was modified after the test.","این طرح پس از آزمایش اصلاح شد."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:monitor','monitor','v','نظارت کردن، پایش کردن','/ˈmɑːnɪtər/ · supervise, observe','If a fan’s picture matches one in the database, security officials could closely monitor him or her and perhaps even make an arrest.','[["If a fan’s picture matches one in the database, security officials could closely monitor him or her and perhaps even make an arrest.","اگر عکس یک تماشاگر با عکسی در پایگاه داده مطابقت داشت، مقامات امنیتی می‌توانستند او را از نزدیک زیر نظر بگیرند و شاید حتی بازداشتش کنند."],["The temperature is carefully monitored.","دما به دقت کنترل می‌شود."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:undertake','undertake','v','بر عهده گرفتن، متعهد شدن','/ˌʌndərˈteɪk/ · promise to do','A biometric system undertakes not just to display or record an event but to instantly identify the people involved in it.','[["A biometric system undertakes not just to display or record an event but to instantly identify the people involved in it.","یک سیستم بیومتریک فقط نمایش یا ضبط یک رویداد را بر عهده نمی‌گیرد، بلکه افراد درگیر در آن را فوراً شناسایی می‌کند."],["Sometimes I undertake more projects than I can finish.","گاهی اوقات من بیش از آنچه می‌توانم به پایان برسانم پروژه‌هایی را انجام می‌دهم."],["The university undertook a major research project.","دانشگاه یک پروژه تحقیقاتی بزرگ را انجام داد."]]','ir2',3,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:accumulate','accumulate','v','انباشته شدن','to gather over time','Neither side in this debate seems likely to accumulate the evidence necessary to settle the matter.','[["Neither side in this debate seems likely to accumulate the evidence necessary to settle the matter.","به نظر نمی‌رسد هیچ‌یک از دو طرف این بحث بتواند شواهد لازم برای حل‌وفصل موضوع را گرد آورد."],["Snow accumulated on the roof.","برف روی پشت بام انباشته شد."],["Dust accumulates quickly in an empty house.","گرد و غبار به سرعت در یک خانه خالی جمع می‌شود."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:adequate','adequate','adj','کافی، مناسب','/ˈædɪkwət/ · sufficient · ≠ inadequate','A background like that could not have been adequate for writing such brilliant plays.','[["A background like that could not have been adequate for writing such brilliant plays.","چنین پیشینه‌ای نمی‌توانست برای نوشتن نمایشنامه‌هایی چنین درخشان کافی باشد."],["He didn''t give an adequate answer to the question.","او پاسخ مناسبی به این سوال نداد."],["The hotel offers adequate parking.","هتل دارای پارکینگ مناسب می‌باشد."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:author','author','n','نویسنده، مؤلف','/ˈɒːθər/ · writer','Oxfordians say the actor Shakespeare was too poorly educated to have been the author of the plays.','[["Oxfordians say the actor Shakespeare was too poorly educated to have been the author of the plays.","آکسفوردی‌ها می‌گویند شکسپیرِ بازیگر تحصیلات بسیار کمی داشت و نمی‌توانست نویسندهٔ این نمایشنامه‌ها باشد."],["He is the author of three books on art.","او نویسنده سه کتاب در زمینه هنر است."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:debate','debate','v','بحث کردن، مناظره کردن','/dɪˈbeɪt/ · discuss','The strongest current debate is between groups known as the Oxfordians and the Stratfordians.','[["The strongest current debate is between groups known as the Oxfordians and the Stratfordians.","داغ‌ترین بحث کنونی میان گروه‌هایی است که به آکسفوردی‌ها و استراتفوردی‌ها معروف‌اند."],["There has been much discussion about prices.","در مورد قیمت‌ها بحث‌های زیادی شده است."],["There is a heated debate about nuclear power.","بحث‌های داغی در مورد انرژی هسته ای وجود دارد."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:depress','depress','v','افسرده کردن؛ کاهش دادن، رکود ایجاد کردن','/dɪˈpres/ · to make sad; to reduce activity or value','For example, the perceptive portrayal of emotional depression in Hamlet seems to indicate that the author had experienced the ailment.','[["For example, the perceptive portrayal of emotional depression in Hamlet seems to indicate that the author had experienced the ailment.","برای مثال، به تصویر کشیدن هوشمندانهٔ افسردگی عاطفی در «هملت» به نظر نشان می‌دهد که نویسنده خود این بیماری را تجربه کرده بود."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:indicate','indicate','v','نشان دادن، حاکی بودن از','/ˈɪndɪkeɪt/ · show, demonstrate','For example, the perceptive portrayal of emotional depression in Hamlet seems to indicate that the author had experienced the ailment.','[["For example, the perceptive portrayal of emotional depression in Hamlet seems to indicate that the author had experienced the ailment.","برای مثال، به تصویر کشیدن هوشمندانهٔ افسردگی عاطفی در «هملت» به نظر نشان می‌دهد که نویسنده خود این بیماری را تجربه کرده بود."],["Research indicates that teachers are dissatisfied with their salary.","تحقیقات نشان می‌دهد که معلمان از حقوق خود ناراضی هستند."],["The results indicate a strong link.","نتایج نشان دهنده یک پیوند قوی است."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:invest','invest','v','سرمایه‌گذاری کردن','/ɪnˈvest/ · put money in sth','He was just an actor and an occasional real-estate investor.','[["He was just an actor and an occasional real-estate investor.","او فقط یک بازیگر و گاه‌گاهی سرمایه‌گذار املاک بود."],["I''ve got a few thousand dollars to invest.","من چند هزار دلار برای سرمایه گذاری دارم."],["The country invested heavily in railways.","این کشور سرمایه گذاری زیادی در راه آهن انجام داد."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:persist','persist','v','پافشاری کردن؛ ادامه یافتن','/pəˈsɪst/ · to continue firmly; to continue to exist','But the Oxford camp persists in their position.','[["But the Oxford camp persists in their position.","اما اردوگاه آکسفوردی‌ها بر موضع خود پافشاری می‌کند."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:precede','precede','v','مقدم بودن بر، پیش از چیزی آمدن','/prɪˈsiːd/ · come before, come first','A great deal of careful work has confirmed these dates, and most Oxfordians reluctantly concede that de Vere’s death preceded the appearance of these plays.','[["A great deal of careful work has confirmed these dates, and most Oxfordians reluctantly concede that de Vere’s death preceded the appearance of these plays.","کار دقیق فراوانی این تاریخ‌ها را تأیید کرده است و بیشتر آکسفوردی‌ها با اکراه می‌پذیرند که مرگ دو ویر پیش از انتشار این نمایشنامه‌ها بوده است."],["in the moments which immediately preceded the earthquake","در لحظاتی که بلافاصله قبل از زلزله بود"]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:protocol','protocol','n','پروتکل، آداب رسمی','/ˈprəʊtəkɑːl/ · customs, rituals, treaty','The Oxford camp claims that de Vere wanted to hide his authorship because it went against protocol for the noble class.','[["The Oxford camp claims that de Vere wanted to hide his authorship because it went against protocol for the noble class.","اردوگاه آکسفوردی‌ها ادعا می‌کند که دو ویر می‌خواست نویسندگی‌اش را پنهان کند، چون این کار خلاف آداب طبقهٔ اشراف بود."],["The soldier''s actions constitute a breach of military protocol.","اقدامات سرباز نقض پروتکل نظامی است."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:reluctance','reluctance','n','بی‌میلی، اکراه','/rɪˈlʌktəns/ · unwillingness to do something','A great deal of careful work has confirmed these dates, and most Oxfordians reluctantly concede that de Vere’s death preceded the appearance of these plays.','[["A great deal of careful work has confirmed these dates, and most Oxfordians reluctantly concede that de Vere’s death preceded the appearance of these plays.","کار دقیق فراوانی این تاریخ‌ها را تأیید کرده است و بیشتر آکسفوردی‌ها با اکراه می‌پذیرند که مرگ دو ویر پیش از انتشار این نمایشنامه‌ها بوده است."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:sustain','sustain','v','حفظ کردن، ادامه دادن؛ متحمل شدن','/səˈsteɪn/ · to keep something going; to experience (damage)','The part hardest to believe is that a plan like that could be sustained for decades without the secret being revealed.','[["The part hardest to believe is that a plan like that could be sustained for decades without the secret being revealed.","باورنکردنی‌ترین بخش این است که چنین نقشه‌ای بتواند دهه‌ها بدون فاش شدن راز ادامه یابد."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:text','text','n','متن','/tekst/ · textbook, passage','In addition, the texts of many Shakespeare plays contain references to events after 1604.','[["In addition, the texts of many Shakespeare plays contain references to events after 1604.","افزون بر این، متن بسیاری از نمایشنامه‌های شکسپیر به رویدادهای پس از ۱۶۰۴ اشاره دارد."],["Students will read and discuss various literary texts.","دانش آموزان متون ادبی مختلف را می‌خوانند و بحث می‌کنند."]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:volume','volume','n','حجم، مقدار؛ جلد (کتاب)','/ˈvɑːljəm/ · amount','The sheer volume of Shakespeare’s work—37 plays, 154 sonnets, 2 other poems, and an elegy—has led to suggestions that “William Shakespeare” was actually several people, not one.','[["The sheer volume of Shakespeare’s work—37 plays, 154 sonnets, 2 other poems, and an elegy—has led to suggestions that “William Shakespeare” was actually several people, not one.","حجم عظیم آثار شکسپیر — ۳۷ نمایشنامه، ۱۵۴ غزل، ۲ شعر دیگر و یک مرثیه — این گمان را پدید آورده که «ویلیام شکسپیر» در واقع چند نفر بوده است، نه یک نفر."],["The volume is too loud. Can you turn the volume down?","صدا خیلی بلند است. میتونی صدا رو کم کنی؟"]]','ir2',4,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:assist','assist','v','کمک کردن، یاری رساندن','/əˈsɪst/ · to help someone do something','Anyone with an Internet connection can find that information in five minutes, without any assistance from a highly paid meteorologist.','[["Anyone with an Internet connection can find that information in five minutes, without any assistance from a highly paid meteorologist.","هر کسی با اتصال اینترنت می‌تواند آن اطلاعات را در پنج دقیقه پیدا کند، بی‌آنکه از یک هواشناس پردرآمد کمک بگیرد."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:coherent','coherent','adj','منسجم','logical and consistent','The expert analysis draws scattered facts together into a coherent picture.','[["The expert analysis draws scattered facts together into a coherent picture.","تحلیل کارشناسانه واقعیت‌های پراکنده را کنار هم می‌گذارد و تصویری منسجم می‌سازد."],["She presented a coherent argument.","او یک استدلال منسجم ارائه کرد."],["He gave a clear and coherent explanation.","او توضیح واضح و منسجمی ارائه کرد."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:core','core','n','هسته، مرکز','/kɔːr/ · central part of sth','His insurance company disputes the core argument of his case—that the damage was done by hail.','[["His insurance company disputes the core argument of his case—that the damage was done by hail.","شرکت بیمهٔ او استدلال اصلی پرونده‌اش را — اینکه خسارت را تگرگ زده است — رد می‌کند."],["Debt is at the core of the problem.","بدهی هسته اصلی مشکل است."],["The Earth''s core is extremely hot.","هسته زمین بسیار داغ است."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:energy','energy','n','انرژی، نیرو','/ˈenərdʒi/ · the ability to do work','The destructive energy of hail, she testifies, produces damage from above, not from the side.','[["The destructive energy of hail, she testifies, produces damage from above, not from the side.","او شهادت می‌دهد که انرژی ویرانگر تگرگ از بالا خسارت ایجاد می‌کند، نه از پهلو."],["Helping people takes time and energy.","کمک به مردم زمان و انرژی می‌خواهد."],["Solar energy is becoming cheaper.","انرژی خورشیدی ارزان‌تر می‌شود"]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:ensure','ensure','v','اطمینان حاصل کردن، تضمین کردن','/ɪnˈʃʊər/ · make sure','So what ensures that someone claiming to be a forensic meteorologist really is?','[["So what ensures that someone claiming to be a forensic meteorologist really is?","پس چه چیزی تضمین می‌کند کسی که ادعا می‌کند هواشناس قضایی است، واقعاً چنین باشد؟"],["The book ensured his success.","کتاب موفقیت او را تضمین کرد."],["Please ensure that all windows are closed.","لطفا مطمئن شوید که همه پنجره‌ها بسته هستند."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:exhibit','exhibit','v','نمایش دادن، به نمایش گذاشتن','/ɪɡˈzɪbɪt/ · show','This case exhibits how meteorology can be considered a branch of forensic science.','[["This case exhibits how meteorology can be considered a branch of forensic science.","این پرونده نشان می‌دهد که چگونه هواشناسی را می‌توان شاخه‌ای از علوم قضایی به شمار آورد."],["They will be exhibiting a collection of paintings.","آنها مجموعه ای از نقاشی‌ها را به نمایش خواهند گذاشت."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:interval','interval','n','فاصله، وقفه','/ˈɪntərvəl/ · period of time between 2 events','But in that short interval, the character of the storm changed.','[["But in that short interval, the character of the storm changed.","اما در همان فاصلهٔ کوتاه، ماهیت طوفان تغییر کرد."],["We see each other at regular intervals -once a month.","ما همدیگر را در فواصل منظم - ماهی یک بار - می‌بینیم."],["Trees were planted at regular intervals.","درختان در فواصل منظم کاشته شدند."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:orient','orient','v','جهت دادن؛ آشنا کردن','/ˈɔːrient/ · to direct toward; to help someone become familiar','An expert''s true value is presenting data to orient you to the general circumstances and then interpreting that data and pointing out possibilities.','[["An expert''s true value is presenting data to orient you to the general circumstances and then interpreting that data and pointing out possibilities.","ارزش واقعی یک کارشناس، ارائهٔ داده‌هایی است که شما را با شرایط کلی آشنا کند و سپس تفسیر آن داده‌ها و نشان دادن احتمالات."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:phenomenon','phenomenon','n','پدیده','/fəˈnɑːmɪnən/ · event, happening','Many people interpreted the brutal heat as evidence that the climate of Earth really has changed, that the phenomenon known as global warming has really set in.','[["Many people interpreted the brutal heat as evidence that the climate of Earth really has changed, that the phenomenon known as global warming has really set in.","بسیاری از مردم گرمای شدید را شاهدی بر این دانستند که آب‌وهوای زمین واقعاً تغییر کرده و پدیدهٔ گرمایش جهانی به‌راستی آغاز شده است."],["natural phenomena like lightning and earthquakes","پدیده‌های طبیعی مانند رعد و برق و زلزله"],["Globalization is a modern phenomenon.","جهانی شدن یک پدیده مدرن است."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:previous','previous','adj','قبلی، پیشین','/ˈpriːviəs/ · past, former','Could the previous witness have seen the defendant talking?','[["Could the previous witness have seen the defendant talking?","آیا ممکن است شاهد قبلی متهم را در حال صحبت دیده باشد؟"],["I had met them the previous day.","روز قبل آنها را ملاقات کرده بودم."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:reinforce','reinforce','v','تقویت کردن','/ˌriːɪnˈfɔːrs/ · strengthen','These doubts are reinforced when the meteorologist explains that radar data also show an extremely strong burst of wind at the farm''s location.','[["These doubts are reinforced when the meteorologist explains that radar data also show an extremely strong burst of wind at the farm''s location.","این تردیدها وقتی تقویت می‌شوند که هواشناس توضیح می‌دهد داده‌های رادار نیز وزش بسیار شدید باد را در محل مزرعه نشان می‌دهند."],["You should reinforce your argument by giving more facts.","شما باید استدلال خود را با ارائه حقایق بیشتر تقویت کنید."],["The walls were reinforced with steel.","دیوارها با فولاد تقویت شدند."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:route','route','n','مسیر، راه','/ruːt/ · way, road','The best route to professional status is to earn the title of Certified Consulting Meteorologist from the American Meteorological Society (AMS).','[["The best route to professional status is to earn the title of Certified Consulting Meteorologist from the American Meteorological Society (AMS).","بهترین راه رسیدن به جایگاه حرفه‌ای، کسب عنوان «هواشناس مشاور رسمی» از انجمن هواشناسی آمریکا (AMS) است."],["We live on a rural route.","ما در یک مسیر روستایی زندگی می‌کنیم."],["The Silk Road was a famous trade route.","جاده ابریشم یک مسیر تجاری معروف بود."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:section','section','n','بخش، قسمت','/ˈsekʃən/ · part, piece','A large section of his cornfield has been flattened.','[["A large section of his cornfield has been flattened.","بخش بزرگی از مزرعهٔ ذرت او خوابیده است."],["She taught three sections of English composition.","او سه بخش آهنگسازی انگلیسی را تدریس کرد."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:strategy','strategy','n','راهبرد، استراتژی','/ˈstrætɪdʒi/ · skilful planning','His strategy was to make the jury doubt what they had just heard.','[["His strategy was to make the jury doubt what they had just heard.","راهبرد او این بود که هیئت‌منصفه را به آنچه تازه شنیده بودند مردد کند."],["He was a genius when it came to military strategy.","او در مورد استراتژی نظامی نابغه بود."]]','ir2',5,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:allocate','allocate','v','تخصیص دادن، اختصاص دادن','/ˈæləkeɪt/ · give,assign','The key to health is to allocate a percentage of your fat intake to each type of fat.','[["The key to health is to allocate a percentage of your fat intake to each type of fat.","کلید سلامتی این است که درصدی از چربی دریافتی خود را به هر نوع چربی اختصاص دهید."],["The government allocated enough funds to infrastructures.","دولت بودجه کافی به زیرساخت‌ها اختصاص داد."],["The council allocated funds to new schools.","شورا بودجه ای را به مدارس جدید اختصاص داد."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:commit','commit','v','متعهد شدن؛ مرتکب شدن','/kəˈmɪt/ · to promise to do something; to do something wrong','It is smart to commit to a balanced-fat diet, not to a no-fat diet.','[["It is smart to commit to a balanced-fat diet, not to a no-fat diet.","عاقلانه است که به یک رژیم با چربی متعادل پایبند شوید، نه به رژیمی بدون چربی."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:compile','compile','v','گردآوری کردن','/kəmˈpaɪl/ · gather together','The research team compiled data on how long each child focused on a toy.','[["The research team compiled data on how long each child focused on a toy.","گروه پژوهشی داده‌هایی گرد آورد دربارهٔ اینکه هر کودک چه مدت روی یک اسباب‌بازی تمرکز می‌کرد."],["He compiled a book of poems.","او کتاب شعری را تنظیم کرد."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:coordinate','coordinate','v','هماهنگ کردن','/kəʊˈɔːdɪneɪt/ · to organize people or things to work together','Many therapists now say they are determined to coordinate psychological therapy with dietary therapy in order to rely less on drugs.','[["Many therapists now say they are determined to coordinate psychological therapy with dietary therapy in order to rely less on drugs.","بسیاری از درمانگران اکنون می‌گویند مصمم‌اند روان‌درمانی را با رژیم‌درمانی هماهنگ کنند تا کمتر به دارو متکی باشند."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:discrete','discrete','adj','مجزا، جداگانه','/dɪˈskriːt/ · separate','Instead of conceiving of it as a single thing, we have to recognize it as several discrete types of a similar compound.','[["Instead of conceiving of it as a single thing, we have to recognize it as several discrete types of a similar compound.","به‌جای اینکه آن را یک چیز واحد تصور کنیم، باید آن را چند نوع مجزا از یک ترکیب مشابه بدانیم."],["The organisms can be divided into discrete categories.","ارگانیسم‌ها را می‌توان به دسته‌های مجزا تقسیم کرد."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:journal','journal','n','مجله (علمی)؛ دفتر خاطرات','/ˈdʒɜːrnl/ · diary','In psychology and physiology journals, articles routinely confirm the value of omega-3 fatty acids.','[["In psychology and physiology journals, articles routinely confirm the value of omega-3 fatty acids.","در مجله‌های روان‌شناسی و فیزیولوژی، مقاله‌ها به‌طور مرتب ارزش اسیدهای چرب امگا-۳ را تأیید می‌کنند."],["He decided to keep a journal.","او تصمیم گرفت که یک دفتر خاطرات داشته باشد."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:mental','mental','adj','ذهنی، روانی','/ˈmentl/ · involving the mind or intellectual processes','A diet high in saturated fat can also make you depressed and antisocial, and impair your general mental performance.','[["A diet high in saturated fat can also make you depressed and antisocial, and impair your general mental performance.","رژیمی سرشار از چربی اشباع‌شده همچنین می‌تواند شما را افسرده و گوشه‌گیر کند و عملکرد ذهنی کلی‌تان را مختل کند."],["The very old man still had all his mental powers.","مرد بسیار پیر هنوز تمام قوای ذهنی خود را داشت."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:overall','overall','adj','کلی، روی‌هم‌رفته','/ˌəʊvərˈɔːl/ · in general','The smart approach is to keep your overall fat intake low and make sure that most of it is in the form of unsaturated fats.','[["The smart approach is to keep your overall fat intake low and make sure that most of it is in the form of unsaturated fats.","رویکرد هوشمندانه این است که کل چربی دریافتی را پایین نگه دارید و مطمئن شوید بیشتر آن به شکل چربی‌های غیراشباع است."],["Overall, the project was successful.","در مجموع این پروژه موفق بود."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:paradigm','paradigm','n','الگو، پارادایم','/ˈpærədaɪm/ · example, model, pattern','To understand its nutritional benefits, however, we have to change the paradigm for how we think about fat.','[["To understand its nutritional benefits, however, we have to change the paradigm for how we think about fat.","اما برای درک فواید تغذیه‌ای آن، باید الگوی فکری‌مان را دربارهٔ چربی تغییر دهیم."],["a new study that challenges the current evolutionary paradigm","مطالعه جدیدی که پارادایم تکاملی کنونی را به چالش می‌کشد"],["The discovery caused a paradigm shift.","این کشف باعث تغییر پارادایم شد."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:period','period','n','دوره، مدت','/ˈpɪəriəd/ · a length of time','These children focused for longer periods and spent much less time simply looking around, unfocused.','[["These children focused for longer periods and spent much less time simply looking around, unfocused.","این کودکان مدت طولانی‌تری تمرکز داشتند و زمان بسیار کمتری را صرف نگاه کردن بی‌هدف به اطراف کردند."],["We had two power failures in a five-month period.","در یک دوره پنج ماهه دو قطع برق داشتیم."],["The Victorian period lasted over 60 years.","دوره ویکتوریا بیش از 60 سال به طول انجامید."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:promote','promote','v','ترفیع دادن؛ ترویج کردن','/prəˈməʊt/ · move to higher rank','Beyond that level, saturated fat may promote heart disease and perhaps some types of cancer.','[["Beyond that level, saturated fat may promote heart disease and perhaps some types of cancer.","فراتر از آن سطح، چربی اشباع‌شده ممکن است بیماری قلبی و شاید برخی انواع سرطان را تشدید کند."],["He was promoted to senior editor.","او به سردبیری ارشد ارتقا یافت."],["The campaign promotes healthy eating.","این کمپین تغذیه سالم را ترویج می‌کند."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:prospect','prospect','n','چشم‌انداز، احتمال','/ˈprɑːspekt/ · view, future','This evidence improves the prospects for treating depressed patients effectively.','[["This evidence improves the prospects for treating depressed patients effectively.","این شواهد چشم‌انداز درمان مؤثر بیماران افسرده را بهتر می‌کند."],["the frightening prospect of going to war","دورنمای ترسناک رفتن به جنگ"],["Graduates face poor job prospects.","فارغ التحصیلان با چشم انداز شغلی ضعیفی روبرو هستند."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:react','react','v','واکنش نشان دادن','/riˈækt/ · to behave in a particular way as a response','The right foods can help you concentrate, keep you motivated, sharpen your memory, speed your reaction time, reduce stress, and perhaps even prevent brain aging.','[["The right foods can help you concentrate, keep you motivated, sharpen your memory, speed your reaction time, reduce stress, and perhaps even prevent brain aging.","غذاهای مناسب می‌توانند به تمرکز شما کمک کنند، انگیزه‌تان را حفظ کنند، حافظه‌تان را تقویت کنند، سرعت واکنشتان را بالا ببرند، استرس را کم کنند و شاید حتی از پیری مغز جلوگیری کنند."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:team','team','n','تیم، گروه','/tiːm/ · a group of people','The research team compiled data on how long each child focused on a toy.','[["The research team compiled data on how long each child focused on a toy.","گروه پژوهشی داده‌هایی گرد آورد دربارهٔ اینکه هر کودک چه مدت روی یک اسباب‌بازی تمرکز می‌کرد."],["The company hired a team of lawyers to advise them.","این شرکت تیمی از وکلا را برای مشاوره به آنها استخدام کرد."]]','ir2',6,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:accommodate','accommodate','v','جا دادن؛ وفق دادن، سازگار کردن','/əˈkɒmədeɪt/ · to provide space for; to adapt to needs','The big opening along Africa’s western coast would easily accommodate the “hump” in South America’s eastern coastline.','[["The big opening along Africa’s western coast would easily accommodate the “hump” in South America’s eastern coastline.","فرورفتگی بزرگ در امتداد ساحل غربی آفریقا به‌راحتی «برآمدگی» ساحل شرقی آمریکای جنوبی را در خود جای می‌دهد."]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:aid','aid','n','کمک، یاری','/eɪd/ · assist, help','Finally, in the late 20th century, the theory of plate tectonics came to the aid of the theory of continental drift.','[["Finally, in the late 20th century, the theory of plate tectonics came to the aid of the theory of continental drift.","سرانجام، در اواخر قرن بیستم، نظریهٔ زمین‌ساخت صفحه‌ای به یاری نظریهٔ رانش قاره‌ها آمد."],["economic/ financial/legal/emergency aid","کمک‌های اقتصادی / مالی / حقوقی / اضطراری"]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:community','community','n','جامعه، اجتماع','/kəˈmjuːnəti/ · society','Even before this theory of plate tectonics became accepted, many in the geological community believed Earth’s continents had moved during the history of the planet.','[["Even before this theory of plate tectonics became accepted, many in the geological community believed Earth’s continents had moved during the history of the planet.","حتی پیش از پذیرفته شدن این نظریهٔ زمین‌ساخت صفحه‌ای، بسیاری در جامعهٔ زمین‌شناسی باور داشتند که قاره‌های زمین در طول تاریخ این سیاره جابه‌جا شده‌اند."],["The festival was a great way for the local community to get together.","این جشنواره راهی عالی برای اجتماع محلی بود."],["The community built a new park.","جامعه یک پارک جدید ساخت."]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:comprehensive','comprehensive','adj','جامع، کامل','/ˌkɑːmprɪˈhensɪv/ · thorough, complete, full','It offered the comprehensive explanation of landmass movement that Wegener had been unable to provide.','[["It offered the comprehensive explanation of landmass movement that Wegener had been unable to provide.","این نظریه توضیح جامعی از حرکت خشکی‌ها ارائه داد که وگنر نتوانسته بود فراهم کند."],["a comprehensive history of the revolution.","تاریخچه جامع انقلاب"],["The report gives a comprehensive overview.","گزارش یک مرور کلی ارائه می‌دهد."]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:displace','displace','v','جابه‌جا کردن، آواره کردن','/dɪsˈpleɪs/ · replace, shift','Catastrophism was displaced by “uniformitarianism,” a term derived from the word uniform.','[["Catastrophism was displaced by “uniformitarianism,” a term derived from the word uniform.","فاجعه‌گرایی جای خود را به «یکنواختی‌گرایی» داد؛ اصطلاحی برگرفته از واژهٔ uniform (یکنواخت)."],["The building of a new dam will displace a lot of people.","ساخت یک سد جدید بسیاری از مردم را آواره خواهد کرد."],["The flood displaced thousands.","سیل هزاران نفر را آواره کرد."]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:evolve','evolve','v','تکامل یافتن','to develop gradually','More geologists began to think that the arrangement of today’s continents gradually evolved.','[["More geologists began to think that the arrangement of today’s continents gradually evolved.","زمین‌شناسان بیشتری به این فکر افتادند که آرایش قاره‌های امروز به‌تدریج تکامل یافته است."],["Birds evolved from dinosaurs.","پرندگان از دایناسورها تکامل یافته اند."],["The company has evolved into a global business.","این شرکت به یک تجارت جهانی تبدیل شده است."]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:fluctuate','fluctuate','v','نوسان داشتن','/ˈflʌktʃueɪt/ · vary, differ','It fluctuates over very long time periods, and has clearly shifted several times.','[["It fluctuates over very long time periods, and has clearly shifted several times.","این میدان در دوره‌های زمانی بسیار طولانی نوسان می‌کند و آشکارا چندین بار جابه‌جا شده است."],["The price of gold continually fluctuates.","قیمت طلا به طور مداوم در نوسان است."],["Oil prices fluctuated throughout the year.","قیمت نفت در طول سال در نوسان بود."]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:integrate','integrate','v','ادغام کردن، یکپارچه کردن','/ˈɪntɪɡreɪt/ · to combine parts into a whole; to become part of a group','It integrated pieces of evidence ranging from volcanic activity to the formation of mountains to the distribution of fossil plants.','[["It integrated pieces of evidence ranging from volcanic activity to the formation of mountains to the distribution of fossil plants.","این نظریه شواهدی از فعالیت آتشفشانی گرفته تا شکل‌گیری کوه‌ها و پراکندگی فسیل‌های گیاهی را یکپارچه کرد."]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:intermediate','intermediate','adj','متوسط، میانی','/ˌɪntərˈmiːdiət/ · middle, midway','One of Wegener’s biggest supporters, Alexander Du Toit, proposed an intermediate stage.','[["One of Wegener’s biggest supporters, Alexander Du Toit, proposed an intermediate stage.","یکی از بزرگ‌ترین حامیان وگنر، الکساندر دو تویت، مرحله‌ای میانی را پیشنهاد کرد."],["intermediate learners of English","زبان آموزان متوسط انگلیسی"]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:nuclear','nuclear','adj','هسته‌ای','/ˈnuːkliər/ · atomic','There were 162 quakes measuring more than 4 on the Richter scale in just two weeks—a quake measuring 5 on the scale releases as much energy as the nuclear explosion that destroyed Hiroshima in World War II.','[["There were 162 quakes measuring more than 4 on the Richter scale in just two weeks—a quake measuring 5 on the scale releases as much energy as the nuclear explosion that destroyed Hiroshima in World War II.","تنها در دو هفته ۱۶۲ زمین‌لرزهٔ بالای ۴ ریشتر رخ داد — زمین‌لرزه‌ای ۵ ریشتری به اندازهٔ انفجار هسته‌ای‌ای که هیروشیما را در جنگ جهانی دوم ویران کرد انرژی آزاد می‌کند."],["the threat of nuclear attack","تهدید حمله هسته ای"]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:random','random','adj','تصادفی','/ˈrændəm/ · by chance','These similarities seemed too numerous to be random coincidences.','[["These similarities seemed too numerous to be random coincidences.","این شباهت‌ها بیش از آن بودند که تصادفی باشند."],["The computer will generate apparently random numbers.","کامپیوتر اعداد ظاهرا تصادفی تولید می‌کند."]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:restrain','restrain','v','مهار کردن، جلوگیری کردن','/rɪˈstreɪn/ · to stop or control someone or something','Then, a revival of science in Europe restrained the imaginations of geographers.','[["Then, a revival of science in Europe restrained the imaginations of geographers.","سپس احیای علم در اروپا تخیل جغرافی‌دانان را مهار کرد."]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:reverse','reverse','adj','معکوس، وارونه','/rɪˈvɜːrs/ · backwards','It also states that the trend toward separation will eventually reverse.','[["It also states that the trend toward separation will eventually reverse.","همچنین بیان می‌کند که روند جدایی سرانجام معکوس خواهد شد."],["Can you say the alphabet in reverse order?","آیا می‌توانید حروف الفبا را به ترتیب معکوس بگویید؟"]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:rigid','rigid','adj','سخت، انعطاف‌ناپذیر','/ˈrɪdʒɪd/ · fixed, firm','In geology, a plate is a large, rigid area of solid rock.','[["In geology, a plate is a large, rigid area of solid rock.","در زمین‌شناسی، صفحه ناحیه‌ای بزرگ و سخت از سنگ جامد است."],["She maintained rigid control over her emotional and sexual life.","او کنترل سفت و سختی بر زندگی عاطفی و جنسی خود داشت."],["The rules are too rigid.","قوانین خیلی سفت و سخت هستند."]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:transform','transform','v','دگرگون کردن','to change completely','According to this explanation, a few sudden, violent events (catastrophes) periodically transformed Earth’s surface.','[["According to this explanation, a few sudden, violent events (catastrophes) periodically transformed Earth’s surface.","بر اساس این توضیح، چند رویداد ناگهانی و خشونت‌بار (فاجعه) به‌طور دوره‌ای سطح زمین را دگرگون کرده‌اند."],["The caterpillar transforms into a butterfly.","کاترپیلار به پروانه تبدیل می‌شود."],["The internet has transformed the way we live.","اینترنت شیوه زندگی ما را دگرگون کرده است."]]','ir2',7,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:arbitrary','arbitrary','adj','دلبخواهی، اختیاری، بی‌قاعده','/ˈɑːrbɪtreri/ · random, casual','Most students mistakenly believe the roommate-assignment system is arbitrary.','[["Most students mistakenly believe the roommate-assignment system is arbitrary.","بیشتر دانشجویان به اشتباه گمان می‌کنند که سیستم تعیین هم‌اتاقی دلبخواهی است."],["He makes unpredictable, arbitrary decisions.","او تصمیمات غیرقابل پیش بینی و خودسرانه می‌گیرد."],["The rules seemed arbitrary.","قوانین خودسرانه به نظر می‌رسید."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:clause','clause','n','بند، ماده (قانون)','/klɔːz/ · an item in a legal document','Clauses in the user agreements for social-networking sites set some rules for profiles, but nothing in the agreement says they have to be true.','[["Clauses in the user agreements for social-networking sites set some rules for profiles, but nothing in the agreement says they have to be true.","بندهای قراردادهای کاربری شبکه‌های اجتماعی قواعدی برای پروفایل‌ها تعیین می‌کنند، اما هیچ‌جای قرارداد نمی‌گوید که باید راست باشند."],["A confidentiality clause was added to the contract.","یک بند محرمانه به قرارداد اضافه شد."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:converse','converse','v','گفت‌وگو کردن؛ عکس، وارونه','/kənˈvɜːs/ · to have a conversation; the opposite','Inside, in the cafeteria, a converse society exists.','[["Inside, in the cafeteria, a converse society exists.","در داخل، در سلف، جامعه‌ای وارونه وجود دارد."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:deviate','deviate','v','منحرف شدن','/ˈdiːvieɪt/ · diverge, stray','Any indication that a roommate’s life deviates from the familiar can heighten a student''s fear of the unknown.','[["Any indication that a roommate’s life deviates from the familiar can heighten a student''s fear of the unknown.","هر نشانه‌ای از اینکه زندگی هم‌اتاقی با چیزهای آشنا تفاوت دارد، می‌تواند ترس دانشجو از ناشناخته‌ها را بیشتر کند."],["deviate from the normal procedure","از روال عادی منحرف شود"]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:diverse','diverse','adj','متنوع','very different from each other','They expect a diverse student body at almost any college, but many students fear diversity as much as they look forward to it.','[["They expect a diverse student body at almost any college, but many students fear diversity as much as they look forward to it.","آن‌ها تقریباً در هر دانشگاهی انتظار جمعیت دانشجویی متنوعی دارند، اما بسیاری از دانشجویان به همان اندازه که مشتاق تنوع‌اند، از آن می‌ترسند."],["London is a diverse city.","لندن شهری متنوع است."],["The city has a diverse population.","این شهر دارای جمعیت متنوعی است."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:domain','domain','n','حوزه، قلمرو','/dəʊˈmeɪn/ · area, realm','They are used to their rooms being their exclusive domains.','[["They are used to their rooms being their exclusive domains.","آن‌ها عادت دارند که اتاقشان قلمرو انحصاری خودشان باشد."],["These documents are in the public domain.","این اسناد در حوزه عمومی هستند."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:gender','gender','n','جنسیت','/ˈdʒendər/ · sex','The school might separate students by gender, they think, but beyond that it’s a matter of chance.','[["The school might separate students by gender, they think, but beyond that it’s a matter of chance.","فکر می‌کنند دانشگاه شاید دانشجویان را بر اساس جنسیت جدا کند، اما فراتر از آن، موضوع شانس است."],["discrimination on the basis of race, gender or age","تبعیض بر اساس نژاد، جنسیت یا سن"]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:guarantee','guarantee','n','ضمانت، تضمین','/ˌɡærənˈtiː/ · assurance','They don’t guarantee roommates will get along, but they succeed much more often than they fail.','[["They don’t guarantee roommates will get along, but they succeed much more often than they fail.","آن‌ها تضمین نمی‌کنند که هم‌اتاقی‌ها با هم کنار بیایند، اما خیلی بیشتر موفق می‌شوند تا ناکام."],["They wanted a guarantee that the document was authentic.","آنها ضمانت می‌خواستند که سند معتبر باشد."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:inevitable','inevitable','adj','اجتناب‌ناپذیر','certain to happen','It’s inevitable that students will worry about potential problems with a roommate—a complete stranger.','[["It’s inevitable that students will worry about potential problems with a roommate—a complete stranger.","اجتناب‌ناپذیر است که دانشجویان نگران مشکلات احتمالی با هم‌اتاقی — یک غریبهٔ کامل — باشند."],["Change is inevitable.","تغییر اجتناب ناپذیر است."],["Change is inevitable in life.","تغییر در زندگی اجتناب ناپذیر است."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:institute','institute','v','برقرار کردن، راه‌اندازی کردن','/ˈɪnstɪtuːt/ · establish','For that reason, some schools have instituted “reality training” for social networkers.','[["For that reason, some schools have instituted “reality training” for social networkers.","به همین دلیل، برخی دانشگاه‌ها «آموزش واقعیت» را برای کاربران شبکه‌های اجتماعی راه انداخته‌اند."],["They have instituted new policies to increase public safety.","آنها سیاست‌های جدیدی را برای افزایش امنیت عمومی وضع کرده اند."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:intervene','intervene','v','مداخله کردن، میانجی‌گری کردن','/ˌɪntərˈviːn/ · involve, intercede','At some campuses, residential-life counselors have decided it’s easier to prevent roommate problems than to intervene in them later.','[["At some campuses, residential-life counselors have decided it’s easier to prevent roommate problems than to intervene in them later.","در برخی دانشگاه‌ها، مشاوران زندگی خوابگاهی به این نتیجه رسیده‌اند که پیشگیری از مشکلات هم‌اتاقی‌ها آسان‌تر از مداخله در آن‌ها در آینده است."],["We do not need further government intervention.","ما نیازی به دخالت بیشتر دولت نداریم."],["The government intervened to stop prices rising.","دولت برای جلوگیری از افزایش قیمت‌ها مداخله کرد."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:maximize','maximize','v','به حداکثر رساندن','/ˈmæksɪmaɪz/ · to make as large or great as possible','The idea is to maximize your attractiveness to people with tastes similar to yours.','[["The idea is to maximize your attractiveness to people with tastes similar to yours.","ایده این است که جذابیت خود را برای افرادی با سلیقه‌های مشابه خودتان به حداکثر برسانید."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:passive','passive','adj','منفعل، غیرفعال','/ˈpæsɪv/ · inactive','Since everything happens anonymously”, normally passive students can spring into investigative action without having to approach a live person.','[["Since everything happens anonymously”, normally passive students can spring into investigative action without having to approach a live person.","از آن‌جا که همه‌چیز به‌صورت ناشناس رخ می‌دهد، دانشجویانی که معمولاً منفعل‌اند می‌توانند بی‌آنکه سراغ یک آدم واقعی بروند، دست به تحقیق بزنند."],["He''s very passive in the relationship.","او در رابطه بسیار منفعل است."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:so-called','so-called','adj','به‌اصطلاح','/ˌsəʊ ˈkɔːld/ · supposed','Students in the so-called millennial generation, in particular, are anxious about sharing a room with another person.','[["Students in the so-called millennial generation, in particular, are anxious about sharing a room with another person.","به‌ویژه دانشجویان نسل موسوم به هزاره، از شریک شدن اتاق با فرد دیگری نگران‌اند."],["The so-called manager had no idea how to manage.","به اصطلاح مدیر هیچ ایده ای برای مدیریت نداشت."]]','ir2',8,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:apparent','apparent','adj','آشکار، ظاهری','/əˈpærənt/ · evident','Someone, apparently not the best speller in town, spray-painted “Terrist” on their property.','[["Someone, apparently not the best speller in town, spray-painted “Terrist” on their property.","کسی که ظاهراً بهترین املانویس شهر نبود، با اسپری روی ملکشان نوشت «تروریست» (با املای غلط)."],["The other team''s superiority was apparent in the game.","برتری تیم مقابل در بازی مشهود بود."],["For no apparent reason, he left.","بدون هیچ دلیل مشخصی رفت."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:assign','assign','v','واگذار کردن، تعیین کردن','/əˈsaɪn/ · designate','When a report, script, article, or manuscript is being prepared, the fact-checkers are assigned to make sure everything is right.','[["When a report, script, article, or manuscript is being prepared, the fact-checkers are assigned to make sure everything is right.","وقتی گزارش، فیلم‌نامه، مقاله یا دست‌نوشته‌ای آماده می‌شود، راستی‌آزمایان مأمور می‌شوند تا از درستی همه‌چیز مطمئن شوند."],["UN troops were assigned the task of rebuilding the hospital.","وظیفه بازسازی بیمارستان به نیروهای سازمان ملل واگذار شد."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:eliminate','eliminate','v','حذف کردن، از بین بردن','/ɪˈlɪməneɪt/ · remove, omit','In far more cases, fact-checking departments have been severely cut back or even eliminated.','[["In far more cases, fact-checking departments have been severely cut back or even eliminated.","در موارد بسیار بیشتری، بخش‌های راستی‌آزمایی به‌شدت کوچک یا حتی حذف شده‌اند."],["Fatty foods should be eliminated from the diet.","غذاهای چرب باید از برنامه غذایی حذف شوند."],["We must eliminate errors from the report.","ما باید خطاهای گزارش را حذف کنیم."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:emphasis','emphasis','n','تأکید','/ˈemfəsɪs/ · stress','Then, in the 1990s, managing editor Tina Brown, emphasizing accuracy, hired the people necessary to restore the department’s good reputation.','[["Then, in the 1990s, managing editor Tina Brown, emphasizing accuracy, hired the people necessary to restore the department’s good reputation.","سپس در دههٔ ۱۹۹۰، سردبیر اجرایی، تینا براون، با تأکید بر دقت، افراد لازم را برای بازگرداندن آبروی خوب این بخش استخدام کرد."],["They placed great emphasis on the individual''s freedom.","آنها تاکید زیادی بر آزادی فرد داشتند."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:ethic','ethic','n','اخلاق، اصول اخلاقی','/ˈeθɪk/ · a set of moral principles','Most journalists believe they have an ethical responsibility to be as accurate as possible.','[["Most journalists believe they have an ethical responsibility to be as accurate as possible.","بیشتر روزنامه‌نگاران معتقدند که مسئولیت اخلاقی دارند تا حد امکان دقیق باشند."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:grant','grant','v','اعطا کردن، پذیرفتن؛ کمک‌هزینه','/ɡrænt/ · admit, permit','Even other publications granted that The New Yorker was the fact-checking champion.','[["Even other publications granted that The New Yorker was the fact-checking champion.","حتی نشریات دیگر هم پذیرفتند که نیویورکر قهرمان راستی‌آزمایی است."],["My request was granted.","درخواست من برآورده شد."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:ignorance','ignorance','n','ناآگاهی، جهل','/ˈɪɡnərəns/ · lack of knowledge or information','The editors of these publications were not ignorant of the president’s disability.','[["The editors of these publications were not ignorant of the president’s disability.","سردبیران این نشریات از معلولیت رئیس‌جمهور بی‌خبر نبودند."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:insert','insert','v','وارد کردن، داخل کردن','/ɪnˈsɜːrt/ · put into, inject','Inserting this one important step in the process might have taken the staff 30 minutes or so.','[["Inserting this one important step in the process might have taken the staff 30 minutes or so.","افزودن همین یک گام مهم به این فرایند شاید حدود ۳۰ دقیقه از وقت کارکنان را می‌گرفت."],["Insert your credit card here.","کارت اعتباری خود را در اینجا وارد کنید."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:levy','levy','n','مالیات، عوارض','/ˈlevi/ · tax','If either the Voricks or the alleged terrorist decides to file a lawsuit, the court could levy huge penalties against the cable network, the commentator, or both.','[["If either the Voricks or the alleged terrorist decides to file a lawsuit, the court could levy huge penalties against the cable network, the commentator, or both.","اگر خانوادهٔ وریک یا تروریستِ ادعایی تصمیم به طرح دعوا بگیرند، دادگاه می‌تواند جریمه‌های سنگینی علیه شبکهٔ کابلی، مفسر یا هر دو وضع کند."],["The government imposed a levy on gasoline.","دولت برای بنزین مالیات وضع کرد."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:perceive','perceive','v','درک کردن، فهمیدن','/pərˈsiːv/ · notice, sense','Many advertisers are nervous about purchasing air time on a network that is perceived as careless.','[["Many advertisers are nervous about purchasing air time on a network that is perceived as careless.","بسیاری از آگهی‌دهندگان از خرید زمان پخش در شبکه‌ای که بی‌دقت تلقی می‌شود نگران‌اند."],["I perceived a change in his behavior.","تغییری در رفتارش احساس کردم."],["How do others perceive you?","دیگران شما را چگونه درک می‌کنند؟"]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:purchase','purchase','v','خریدن، خریداری کردن','/ˈpɜːrtʃɪs/ · buy','Many advertisers are nervous about purchasing air time on a network that is perceived as careless.','[["Many advertisers are nervous about purchasing air time on a network that is perceived as careless.","بسیاری از آگهی‌دهندگان از خرید زمان پخش در شبکه‌ای که بی‌دقت تلقی می‌شود نگران‌اند."],["Tickets may be purchased in advance from the box office.","بلیط‌ها را می‌توان از قبل از گیشه خریداری کرد."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:restrict','restrict','v','محدود کردن','/rɪˈstrɪkt/ · limit','A copy editor might occasionally question a “fact” that seems incorrect, but newspapers operate under severe time restrictions.','[["A copy editor might occasionally question a “fact” that seems incorrect, but newspapers operate under severe time restrictions.","ویراستار ممکن است گاهی «واقعیتی» را که نادرست به نظر می‌رسد زیر سؤال ببرد، اما روزنامه‌ها با محدودیت‌های زمانی شدیدی کار می‌کنند."],["He is on a severely restricted diet.","او در رژیم غذایی به شدت محدود است."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:submit','submit','v','ارائه دادن، تسلیم کردن؛ تسلیم شدن','/səbˈmɪt/ · give in, accept','Reporters are expected to get the facts right in the copy they submit.','[["Reporters are expected to get the facts right in the copy they submit.","از خبرنگاران انتظار می‌رود واقعیت‌ها را در متنی که ارائه می‌کنند درست بیاورند."],["All countries in the EU must submit to its laws.","همه کشورهای اتحادیه اروپا باید تابع قوانین آن باشند."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:successor','successor','n','جانشین','/səkˈsesə(r)/ · a person or thing that comes after another','Photo-editing software is simply a far smarter successor to those tools.','[["Photo-editing software is simply a far smarter successor to those tools.","نرم‌افزار ویرایش عکس صرفاً جانشینی بسیار هوشمندتر برای آن ابزارهاست."]]','ir2',9,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:append','append','v','پیوست کردن، افزودن (به انتها)','/əˈpend/ · to add something at the end of a text','Like their close relatives, the bees, many species of ant have a sharp appendage, called a stinger, at the end of their body.','[["Like their close relatives, the bees, many species of ant have a sharp appendage, called a stinger, at the end of their body.","بسیاری از گونه‌های مورچه، مانند خویشاوندان نزدیکشان یعنی زنبورها، زائده‌ای تیز به نام نیش در انتهای بدنشان دارند."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:chemical','chemical','n','ماده شیمیایی؛ شیمیایی','/ˈkemɪkl/ · n., adj. · a substance produced by a chemical process','These cells are filled with a chemical called “histamine.','[["These cells are filled with a chemical called “histamine.","این سلول‌ها پر از ماده‌ای شیمیایی به نام «هیستامین» هستند."],["The teacher showed us two kinds of chemical reactions today.","معلم امروز دو نوع واکنش شیمیایی را به ما نشان داد."],["Farmers use chemicals to protect their crops.","کشاورزان برای محافظت از محصولات خود از مواد شیمیایی استفاده می‌کنند."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:circumstance','circumstance','n','شرایط، موقعیت','/ˈsɜːrkəmstæns/ · situation','Following World War II, circumstances in the U.S. worked in the ants’ favor.','[["Following World War II, circumstances in the U.S. worked in the ants’ favor.","پس از جنگ جهانی دوم، شرایط در آمریکا به سود مورچه‌ها پیش رفت."],["The circumstances of his death are suspicious.","شرایط مرگ او مشکوک است."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:contact','contact','n','تماس، ارتباط','/ˈkɒntækt/ · the act of communicating with somebody','The venom is also necrotic—it kills the tissue that it comes in contact with.','[["The venom is also necrotic—it kills the tissue that it comes in contact with.","این زهر همچنین بافت‌مرده‌ساز است — بافتی را که با آن تماس پیدا کند می‌کشد."],["Many of us have no direct contact with elderly people.","بسیاری از ما هیچ ارتباط مستقیمی با افراد مسن نداریم."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:estimate','estimate','n','تخمین؛ برآورد کردن','/ˈestəmət/ · n., v. · calculate, judge','Public health experts estimate that, in any given year, from 30 to 60 percent of people living in Solenopsis zones in the United States are stung.','[["Public health experts estimate that, in any given year, from 30 to 60 percent of people living in Solenopsis zones in the United States are stung.","کارشناسان بهداشت عمومی برآورد می‌کنند که در هر سال، ۳۰ تا ۶۰ درصد از ساکنان مناطق سولنوپسیس در آمریکا نیش می‌خورند."],["It is not easy to estimate how many people have the disease.","تخمین زدن تعداد افراد مبتلا به این بیماری آسان نیست."],["Scientists estimate that the tree is 2,000 years old.","دانشمندان تخمین می‌زنند که این درخت 2000 سال سن دارد."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:external','external','adj','خارجی، بیرونی','/ɪkˈstɜːrnl/ · outside','Under these circumstances, external temperatures would make no difference at all, and fire ants would become a much bigger problem for humans.','[["Under these circumstances, external temperatures would make no difference at all, and fire ants would become a much bigger problem for humans.","در چنین شرایطی، دمای بیرون هیچ تفاوتی ایجاد نمی‌کرد و مورچه‌های آتشین به مشکلی بسیار بزرگ‌تر برای انسان تبدیل می‌شدند."],["The external walls of the building","دیوارهای خارجی ساختمان"]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:initiate','initiate','v','آغاز کردن، راه‌اندازی کردن','to cause something to begin','That landing in Alabama initiated a full-scale invasion.','[["That landing in Alabama initiated a full-scale invasion.","آن ورود به آلاباما، آغازگر یک هجوم تمام‌عیار بود."],["The government initiated a program to plant trees.","دولت برنامه ای را برای کاشت درخت آغاز کرد."],["Who initiated the conversation?","چه کسی گفتگو را آغاز کرد؟"]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:minimal','minimal','adj','حداقل، بسیار کم','/ˈmɪnɪml/ · least','Immunotherapy is currently the best option for minimalizing reactions.','[["Immunotherapy is currently the best option for minimalizing reactions.","ایمنی‌درمانی در حال حاضر بهترین گزینه برای به حداقل رساندن واکنش‌هاست."],["This is a practical course, with only a minimal amount of theory.","این یک دوره عملی است و تنها دارای حداقل مقدار تئوری است."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:neutral','neutral','adj','بی‌طرف، خنثی','/ˈnuːtrəl/ · impartial, unbiased','Nothing can completely neutralize the effects of fire-ant venom, but people sensitive to it who live in fire-ant territory have some treatment choices.','[["Nothing can completely neutralize the effects of fire-ant venom, but people sensitive to it who live in fire-ant territory have some treatment choices.","هیچ چیز نمی‌تواند اثرات زهر مورچهٔ آتشین را کاملاً خنثی کند، اما افراد حساس به آن که در قلمرو این مورچه‌ها زندگی می‌کنند گزینه‌های درمانی‌ای دارند."],["When her friends had a quarrel, she remained neutral.","وقتی دوستانش دعوا می‌کردند، بی طرف می‌ماند."],["Switzerland remained neutral during the war.","سوئیس در طول جنگ بی طرف ماند."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:percent','percent','n','درصد','/pərˈsent/ · per hundred (%)','Public health experts estimate that, in any given year, from 30 to 60 percent of people living in Solenopsis zones in the United States are stung.','[["Public health experts estimate that, in any given year, from 30 to 60 percent of people living in Solenopsis zones in the United States are stung.","کارشناسان بهداشت عمومی برآورد می‌کنند که در هر سال، ۳۰ تا ۶۰ درصد از ساکنان مناطق سولنوپسیس در آمریکا نیش می‌خورند."],["New car sales may be down nineteen percent.","فروش خودروهای جدید ممکن است نوزده درصد کاهش یابد."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:regime','regime','n','رژیم، نظام حکومتی','/reɪˈʒiːm/ · government, diet','The immunotherapy regime is expensive, and it also requires a long-term commitment.','[["The immunotherapy regime is expensive, and it also requires a long-term commitment.","روش ایمنی‌درمانی گران است و همچنین به تعهدی بلندمدت نیاز دارد."],["The new regime is sure to fall.","رژیم جدید قطعا سقوط خواهد کرد."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:sufficient','sufficient','adj','کافی','/səˈfɪʃənt/ · enough · ≠ insufficient','Eventually, patients have sufficient defenses to tolerate a fire-ant sting.','[["Eventually, patients have sufficient defenses to tolerate a fire-ant sting.","سرانجام بیماران دفاع کافی برای تحمل نیش مورچهٔ آتشین پیدا می‌کنند."],["He had an income which was sufficient for his needs.","درآمدی داشت که برای نیازهایش کافی بود."],["We have sufficient food for a week.","برای یک هفته غذای کافی داریم."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:summary','summary','n','خلاصه','/ˈsʌməri/ · abstract','In summary, research shows that, like any insect, a fire ant becomes less active as the weather grows colder.','[["In summary, research shows that, like any insect, a fire ant becomes less active as the weather grows colder.","به‌طور خلاصه، پژوهش‌ها نشان می‌دهند که مورچهٔ آتشین مانند هر حشرهٔ دیگری، با سردتر شدن هوا کم‌تحرک‌تر می‌شود."],["A brief summary is given on a separate sheet.","خلاصه ای مختصر در یک برگه جداگانه آورده شده است."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ir2:virtual','virtual','adj','مجازی؛ تقریباً کامل','/ˈvɜːtʃuəl/ · created by computers; almost but not completely','Virtually everyone who is stung by a fire ant develops a red welt that stays painful for several days.','[["Virtually everyone who is stung by a fire ant develops a red welt that stays painful for several days.","تقریباً هر کسی که مورچهٔ آتشین نیشش بزند، دچار برآمدگی قرمزی می‌شود که چند روز دردناک می‌ماند."]]','ir2',10,1792279535294,1792279535294) ON CONFLICT(slug) DO UPDATE SET word=excluded.word, pos=excluded.pos, meaning_fa=excluded.meaning_fa, definition=excluded.definition, example=excluded.example, examples=excluded.examples, category_id=excluded.category_id, level_no=excluded.level_no, updated_at=excluded.updated_at;
